INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-2898910DDF35929DD3AF','research',NULL,'Faculty Positions in Institute of Genetics and Developmental Biology, Chinese Academy of Sciences----Center for Agricultural Resources Research, Institute of Genetics？and Developmental Biology, Chinese Academy of Sciences','http://english.sjziam.cas.cn/ju/201808/t20180823_196510.html',NULL,'*Center for Agricultural Resources Research',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:04:32.685Z','institutional_primary','en','In order to meet the national demands and aim at international frontiers in the related areas,the Center for Agricultural Resources Research (CARR), Institute of Genetics and Developmental Biology of CAS，considering the particular agricultural needs of efficient utilization of water resources in North China Plain as well, has put stress on the following areas: plant physiology and ecology of drought tolerance, farmland water transfer and development of water saving technologies, agricultural water resource management and safety, molecular genetics and breeding for new cultivars with desired traits of water-saving, high quality and high yield.','In order to meet the national demands and aim at international frontiers in the related areas,the Center for Agricultural Resources Research (CARR), Institute of Genetics and Developmental Biology of CAS，considering the particular agricultural needs of efficient utilization of water resources in North China Plain as well, has put stress on the following areas: plant physiology and ecology of drought tolerance, farmland water transfer and development of water saving technologies, agricultural water resource management and safety, molecular genetics and breeding for new cultivars with desired traits of water-saving, high quality and high yield.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.sjziam.cas.cn/ju/201808/t20180823_196510.html',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','a4f0f754985edb163ed0793471ed4b3f73a19c52ef302451b6f5b02a0d0ee068','2898910ddf35929dd3afb3c9b95dbe16912692aa43fa1749a3121a3926246160',1,1,1,1 FROM sources WHERE root_url='http://english.sjziam.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
