INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-6793F1CF8919520320BC','research',NULL,'Research Group of Shen Yanjun Makes New Progress in Quantifying Contributions to Groundwater Recovery in the North China Plain----Center for Agricultural Resources Research, Institute of Genetics？and Developmental Biology, Chinese Academy of Sciences','http://english.sjziam.cas.cn/ne/es/202609/t20260910_1197718.html',NULL,'*Center for Agricultural Resources Research',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:04:32.872Z','institutional_primary','en','The North China Plain is a crucial grain-producing region in China; however, long-term groundwater overexploitation has severely threatened regional water resource security and agricultural sustainability. In recent years, due to the operation of the South-to-North Water Diversion Project, the implementation of groundwater extraction reduction policies, and increased precipitation, groundwater levels in the region have begun to recover. Nevertheless, a systematic quantitative study on the respective contributions of increased precipitation, reduced groundwater pumping, and external water diversion to groundwater recovery, as well as their variations across different cities, has been lacking.','The North China Plain is a crucial grain-producing region in China; however, long-term groundwater overexploitation has severely threatened regional water resource security and agricultural sustainability. In recent years, due to the operation of the South-to-North Water Diversion Project, the implementation of groundwater extraction reduction policies, and increased precipitation, groundwater levels in the region have begun to recover. Nevertheless, a systematic quantitative study on the respective contributions of increased precipitation, reduced groundwater pumping, and external water diversion to groundwater recovery, as well as their variations across different cities, has been lacking.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.sjziam.cas.cn/ne/es/202609/t20260910_1197718.html',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','13ae350d4e44162d128682ef856ed665e00b55f1e929000c01c53a63e062e569','6793f1cf8919520320bccc4f037f1007b4175791ecdc650bdf7d6a93d8850bd9',1,1,1,1 FROM sources WHERE root_url='http://english.sjziam.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
