INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-BBE5E8F52E1561755578','research',NULL,'Researchers Estimate Winter Soil CO2 Flux from Different Mid-Latitude Sites of Middle Taihang Mountain in North China----Center for Agricultural Resources Research, Institute of Genetics？and Developmental Biology, Chinese Academy of Sciences','http://english.sjziam.cas.cn/rh/rp/201808/t20180823_196531.html',NULL,'*Center for Agricultural Resources Research',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:04:32.473Z','institutional_primary','en','Soil respiration provides the main carbon flux from terrestrial ecosystems to the atmosphere. Most soil respiration measurements are conducted during the plant-growing season. Yet small but continuous rates of ecosystem soil respiration during the winter can, in some cases, completely determine annual rates of carbon sequestration. Mid-latitude ecosystems are considered to be major terrestrial carbon sinks in the northern hemisphere. However, little is known about the winter soil respiration and its contribution to annual soil CO 2 flux in different mid-latitude ecosystems, which may yield inaccurate regional and global C budget predictions.','Soil respiration provides the main carbon flux from terrestrial ecosystems to the atmosphere. Most soil respiration measurements are conducted during the plant-growing season. Yet small but continuous rates of ecosystem soil respiration during the winter can, in some cases, completely determine annual rates of carbon sequestration. Mid-latitude ecosystems are considered to be major terrestrial carbon sinks in the northern hemisphere. However, little is known about the winter soil respiration and its contribution to annual soil CO 2 flux in different mid-latitude ecosystems, which may yield inaccurate regional and global C budget predictions.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.sjziam.cas.cn/rh/rp/201808/t20180823_196531.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','c01b489172789bfba845983626b35ca71916474a728e9f5a37087d56e7c69023','bbe5e8f52e1561755578f661cb6f8cebac32a22eec189dc0d9752d6f147dc8d0',1,1,1,1 FROM sources WHERE root_url='http://english.sjziam.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'researchers estimate winter soil co2 flux from different mid-latitude sites of middle taihang mountain in north china----center for agricultural resources research institute of genetics and developmental biology chinese academy of sciences soil respiration provides the main carbon flux from terrestrial ecosystems to the atmosphere. most soil respiration measurements are conducted during the plant-growing season. yet small but continuous rates of ecosystem soil respiration during the winter can in some cases completely determine annual rates of carbon sequestration. mid-latitude ecosystems are considered to be major terrestrial carbon sinks in the northern hemisphere. however little is known about the winter soil respiration and its contribution to annual soil co 2 flux in different mid-latitude ecosystems which may yield inaccurate regional and global c budget predictions. research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='bbe5e8f52e1561755578f661cb6f8cebac32a22eec189dc0d9752d6f147dc8d0' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
