INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-EC4AA7799C37A1F76201','research',NULL,'Binaries & Variables Group----Yunnan Observatories','https://english.ynao.cas.cn/research/rg/bvg/',NULL,'*Yunnan Observatories',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:05:19.389Z','institutional_primary','en','Following the application of knowledge gained from studies of stellar evolution and stellar atmospheres to binary studies in the 1950s and 60s, mankind began to probe into the physics behind binary systems and their evolution. Relevant theories started being formulated in the 1970s, which was also when Yunnan Observatories started showing an interest in this field. Over the past few decades, the binaries & variables group has observed and studied many such objects, most notably W Ursae Majoris variables, and made considerable discoveries in the field.','Following the application of knowledge gained from studies of stellar evolution and stellar atmospheres to binary studies in the 1950s and 60s, mankind began to probe into the physics behind binary systems and their evolution. Relevant theories started being formulated in the 1970s, which was also when Yunnan Observatories started showing an interest in this field. Over the past few decades, the binaries & variables group has observed and studied many such objects, most notably W Ursae Majoris variables, and made considerable discoveries in the field.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://english.ynao.cas.cn/research/rg/bvg/',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','eeffbd731fd93adbc44e8bf8f56f9eecd85ee38e43ebbc9c29597eaa957af2d6','ec4aa7799c37a1f76201e2bfd1fdc0d87f244ce9b78313c3a9010bd26d6eefab',1,1,1,1 FROM sources WHERE root_url='https://english.ynao.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
