INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-451984153016656977B7','research',NULL,'Key Labroratory for the Structure and Evolution of Celestial Objects, CAS----Yunnan Observatories','https://english.ynao.cas.cn/research/kl/klseco/',NULL,'*Yunnan Observatories',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:05:18.420Z','institutional_primary','en','The Key Laboratory for the Structure and Evolution of Celestial Objects, a subsidiary of Yunnan Observatories, was established in December 2012 under the approval of the Chinese Academy of Sciences. The laboratory consists of the binary population synthesis, stellar astrophysics, binaries & variables, high energy astrophysics and radio astronomy research groups, as well as the Lijiang observing station. Fields of research addressed by the laboratory include planetary and stellar astrophysics, binaries, galaxies, AGNs, accretion disks, etc. Current instrumentation covers photometry and spectrometry from radio to optical wavelengths, including the 2.4m optical telescope, the 1m optical telescope, the 60cm optical telecope, the 40m radio telescope, BOOTES-4, the 1.8m optical telescope, among others.','The Key Laboratory for the Structure and Evolution of Celestial Objects, a subsidiary of Yunnan Observatories, was established in December 2012 under the approval of the Chinese Academy of Sciences. The laboratory consists of the binary population synthesis, stellar astrophysics, binaries & variables, high energy astrophysics and radio astronomy research groups, as well as the Lijiang observing station. Fields of research addressed by the laboratory include planetary and stellar astrophysics, binaries, galaxies, AGNs, accretion disks, etc. Current instrumentation covers photometry and spectrometry from radio to optical wavelengths, including the 2.4m optical telescope, the 1m optical telescope, the 60cm optical telecope, the 40m radio telescope, BOOTES-4, the 1.8m optical telescope, among others.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://english.ynao.cas.cn/research/kl/klseco/',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','3a6dfbb57146fbb97e1cd30c189b3b0a9ce837317908612c067ba423cc14f74c','451984153016656977b7395f01b5e6745273c79a98e6e9906ffcbdbc83c5ce0a',1,1,1,1 FROM sources WHERE root_url='https://english.ynao.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
