INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-D67F3B494B67885F651E','research',NULL,'Solar Site Survey and Coronal Observation Group----Yunnan Observatories','https://english.ynao.cas.cn/research/rg/ssscog/',NULL,'*Yunnan Observatories',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:05:19.395Z','institutional_primary','en','To advance the technique of ground-based observations and to solve the fundamental problems of solar physics, it is essential that optimum sites be allocated for the purpose of optical and IR solar observations in the near future. The western inland regions of China boast a homogeneous and stable atmosphere, an ample amount of sunlight hours, in addition to a high altitude. Such properties are ideal for solar observation, yet the region remains untouched by researchers in the field due to underdevelopment in the related areas. Therefore, prospecting for sites in these regions is a worthwhile activity for the development of solar research.','To advance the technique of ground-based observations and to solve the fundamental problems of solar physics, it is essential that optimum sites be allocated for the purpose of optical and IR solar observations in the near future. The western inland regions of China boast a homogeneous and stable atmosphere, an ample amount of sunlight hours, in addition to a high altitude. Such properties are ideal for solar observation, yet the region remains untouched by researchers in the field due to underdevelopment in the related areas. Therefore, prospecting for sites in these regions is a worthwhile activity for the development of solar research.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://english.ynao.cas.cn/research/rg/ssscog/',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','7da40ce7acbc7da1f18b4ef8836d86515b1c4eac37717f071784c8a6d29764c0','d67f3b494b67885f651ea81ab5ece2090f45694b0ff9be1532de1d1495bda2a0',1,1,1,1 FROM sources WHERE root_url='https://english.ynao.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
