INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-7FBF2E036AECCACD03B5','research',NULL,'Study Confirms Compact Companion around the RR Lyrae Star IY Lyr----Yunnan Observatories','https://english.ynao.cas.cn/research/rp/202609/t20260930_1201606.html',NULL,'*Yunnan Observatories',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:05:18.215Z','institutional_primary','en','Researchers from the Yunnan Observatories (Chinese Academy of Sciences), working with the Ulugh Beg Astronomical Institute of Uzbekistan, have identified a compact companion orbiting the RR Lyrae star IY Lyr. By combining photometric, spectroscopic, and astrometric data—including LAMOST (Large Sky Area Multi-Object Fiber Spectroscopic Telescope) spectroscopy, ZTF (Zwicky Transient Facility), TESS (Transiting Exoplanet Survey Satellite), ASAS-SN (All-Sky Automated Survey for Supernovae), and dedicated BVRI observations from the Maidanak 60-cm telescope—they provided the first robust evidence for a companion with a mass of 1.37 solar masses around this RRc-type variable star.','Researchers from the Yunnan Observatories (Chinese Academy of Sciences), working with the Ulugh Beg Astronomical Institute of Uzbekistan, have identified a compact companion orbiting the RR Lyrae star IY Lyr. By combining photometric, spectroscopic, and astrometric data—including LAMOST (Large Sky Area Multi-Object Fiber Spectroscopic Telescope) spectroscopy, ZTF (Zwicky Transient Facility), TESS (Transiting Exoplanet Survey Satellite), ASAS-SN (All-Sky Automated Survey for Supernovae), and dedicated BVRI observations from the Maidanak 60-cm telescope—they provided the first robust evidence for a companion with a mass of 1.37 solar masses around this RRc-type variable star.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://english.ynao.cas.cn/research/rp/202609/t20260930_1201606.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','f98a30257527070b42bc4470ee1b1f52bc73a52d4bb7f27ea6ee7b717a9fd034','7fbf2e036aeccacd03b5dec8d68209d25690a63c545f09291a7337a3c666650d',1,1,1,1 FROM sources WHERE root_url='https://english.ynao.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'study confirms compact companion around the rr lyrae star iy lyr----yunnan observatories researchers from the yunnan observatories chinese academy of sciences working with the ulugh beg astronomical institute of uzbekistan have identified a compact companion orbiting the rr lyrae star iy lyr. by combining photometric spectroscopic and astrometric data including lamost large sky area multi-object fiber spectroscopic telescope spectroscopy ztf zwicky transient facility tess transiting exoplanet survey satellite asas-sn all-sky automated survey for supernovae and dedicated bvri observations from the maidanak 60-cm telescope they provided the first robust evidence for a companion with a mass of 1.37 solar masses around this rrc-type variable star. research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='7fbf2e036aeccacd03b5dec8d68209d25690a63c545f09291a7337a3c666650d' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-2740D05FF8448435FAE9','research',NULL,'A Letter of Support from the Academy of Mathematics and Systems Science, Chinese Academy of Sciences, for Hong Kong’s Bid to Host the International Congress of Mathematicians 2030----Academy of Mathematics and Systems Science','http://english.amss.cas.cn/ae/news/202605/t20260514_1159378.html',NULL,'Academy of Mathematics and Systems Science',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:05:17.888Z','institutional_primary','en','The Academy of Mathematics and Systems Science (AMSS) of the Chinese Academy of Sciences (CAS), was founded in December 1998 with the integration of the Institute of Mathematics (established 1952), the Institute of Applied Mathematics (established 1979), the Institute of Systems Science (established 1979), the Institute of Computational Mathematics and Scientific/Engineering Computing (established 1995). CAS Academician Prof. YANG Lo was its founding president, CAS Academician Prof. GUO Lei was the second president, CAS Academician Prof. XI Nanhua and Prof. WANG Yuefei were the third co-presidents, and CAS Academician Prof. XI Nanhua is the current president.','The Academy of Mathematics and Systems Science (AMSS) of the Chinese Academy of Sciences (CAS), was founded in December 1998 with the integration of the Institute of Mathematics (established 1952), the 