INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-B02E3FCF54EA5EC3F8B0','research',NULL,'The 6th Symposium on Computational Imaging Technology and Applications successfully held----Chongqing Insitute of Green and Intelligent Technology','http://english.cigit.cas.cn/nw/academicactivities/202405/t20240531_664665.html',NULL,'Chongqing Institute of Green and Intelligent Technology','中国科学院','China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:06:43.571Z','institutional_primary','en','The conference invited well-known experts and scholars in the field of computational imaging to exchange, in-depth discussion of cutting-edge technologies and latest research results in the field of computational imaging, aimed at promoting the development of computational imaging technology, providing a stage for personnel in related fields to exchange new ideas and new technologies, and promoting scientific and technological innovation and achievement transformation in related disciplines. Improve the teaching and research level of computational imaging research and the influence of computational imaging research in the field of photoelectric imaging technology. The seminar attracted more than 500 experts and scholars from universities, research institutes and enterprises all over the country.','The conference invited well-known experts and scholars in the field of computational imaging to exchange, in-depth discussion of cutting-edge technologies and latest research results in the field of computational imaging, aimed at promoting the development of computational imaging technology, providing a stage for personnel in related fields to exchange new ideas and new technologies, and promoting scientific and technological innovation and achievement transformation in related disciplines. Improve the teaching and research level of computational imaging research and the influence of computational imaging research in the field of photoelectric imaging technology. The seminar attracted more than 500 experts and scholars from universities, research institutes and enterprises all over the country.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.cigit.cas.cn/nw/academicactivities/202405/t20240531_664665.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','f6e573d84c6d376848ce8d06bf173a16885ab342fa3b107c2aed270fba1c55ab','b02e3fcf54ea5ec3f8b0506bc16ef89b86bab79e4ffd3430b0ecb742c3933629',1,1,1,1 FROM sources WHERE root_url='http://english.cigit.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
