INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-1AF1B410A37B16F87B3B','research',NULL,'Researchers Report Organic Metal Chalcogenide Films with Giant Birefringence----Fujian Institute of Research on the Structure of Matter Chinese Academy of Sciences','http://english.fjirsm.cas.cn/rh/rps/202609/t20260930_1201586.html',NULL,'Fujian Institute of Research on the Structure of Matter',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:07:14.332Z','institutional_primary','en','With the development of integrated optics, birefringent materials urgently need to shift from bulk crystals to film form. However, when traditional birefringent materials are transformed from bulk crystals to films, their performance significantly deteriorates. Their optical anisotropy usually retains only about 20% of that of the bulk crystals, which severely restricts the application of films in integrated photonic devices.','With the development of integrated optics, birefringent materials urgently need to shift from bulk crystals to film form. However, when traditional birefringent materials are transformed from bulk crystals to films, their performance significantly deteriorates. Their optical anisotropy usually retains only about 20% of that of the bulk crystals, which severely restricts the application of films in integrated photonic devices.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.fjirsm.cas.cn/rh/rps/202609/t20260930_1201586.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','d3c96b6b80f5b856eeedd41ed037b5bf775e1b5588b27360d5947cab4893f67c','1af1b410a37b16f87b3b95c794bf17029e866fd7d7a1edc268030fc987fa7a6a',1,1,1,1 FROM sources WHERE root_url='http://english.fjirsm.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
