INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-F9B66849294C96546B08','research',NULL,'Center for Research on Intelligent Perception and Computing----Institute of Automation','http://english.ia.cas.cn/rd/201510/t20151013_153432.html',NULL,'Institute of Automation',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:09:14.688Z','institutional_primary','en','The Center for Research on Intelligent Perception and Computing (CRIPAC) is affiliated to the Institute of Automation, Chinese Academy of Sciences (CAS). Focusing on the theory and technology of intelligent perception and computing, the Center aims at conducting cutting-edge research and applications, and strives to build a world-class research organization in terms of personnel training, technological innovation and technology transfer. Currently, the research area of CRIPAC is mainly focused on information sensing, intelligent recognition, content security, system integration and applications.','The Center for Research on Intelligent Perception and Computing (CRIPAC) is affiliated to the Institute of Automation, Chinese Academy of Sciences (CAS). Focusing on the theory and technology of intelligent perception and computing, the Center aims at conducting cutting-edge research and applications, and strives to build a world-class research organization in terms of personnel training, technological innovation and technology transfer. Currently, the research area of CRIPAC is mainly focused on information sensing, intelligent recognition, content security, system integration and applications.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.ia.cas.cn/rd/201510/t20151013_153432.html',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','0f145be0b58dc45a7b1c49b8fdb7040524c868854b1d3b3fb119c3f5485475d8','f9b66849294c96546b085225aa50f879a52bd97918a0a79f967806d0c5c8d720',1,1,1,1 FROM sources WHERE root_url='http://english.ia.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
