INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-4259A9C106F047897FA2','research',NULL,'National Laboratory of Pattern Recognition----Institute of Automation','http://english.ia.cas.cn/rd/200908/t20090807_27604.html',NULL,'Institute of Automation',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:09:14.293Z','institutional_primary','en','National Laboratory of Pattern Recognition (NLPR) approved by State Development Planning Commission was built in 1984. In 1987 it passed state examination and was formally open to the outside, relied on Institute of Automation, Chinese Academy of Sciences (CASIA), as one of the first state key laboratories in China. The first director of NLPR is Prof. MA Songde, who is the incumbent vice minister of Ministry of Science and Technology (MOST). The incumbent director of NLPR is Prof. LIU Chenglin. Prof. TAN Tieniu, CAS Member, is the director of academic committee.','National Laboratory of Pattern Recognition (NLPR) approved by State Development Planning Commission was built in 1984. In 1987 it passed state examination and was formally open to the outside, relied on Institute of Automation, Chinese Academy of Sciences (CASIA), as one of the first state key laboratories in China. The first director of NLPR is Prof. MA Songde, who is the incumbent vice minister of Ministry of Science and Technology (MOST). The incumbent director of NLPR is Prof. LIU Chenglin. Prof. TAN Tieniu, CAS Member, is the director of academic committee.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.ia.cas.cn/rd/200908/t20090807_27604.html',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','17c424806a98ce843c8214cd1f255a430fa57dfe25a707932270e223eb63c1f6','4259a9c106f047897fa20d7edd9072526ddbfe6f1cf38219e556cb642dd3260e',1,1,1,1 FROM sources WHERE root_url='http://english.ia.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
