INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-C18C962D6F68AF8A6F94','research',NULL,'Research Center for Brain-inspired Intelligence----Institute of Automation','http://english.ia.cas.cn/rd/201412/t20141202_132383.html',NULL,'Institute of Automation',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:09:14.690Z','institutional_primary','en','Brain-inspired Intelligence is a long term strategic scientific program proposed by Institute of Automation, Chinese Academy of Sciences (CASIA). It is based on the vision of the institute which emphasize the trend on the evolution from Automation to Information Technology, and ultimately to Intelligence Science. Brain-inspired Intelligence is the grand challenge for achieving Human-level Artificial Intelligence. The efforts on Brain-inspired Intelligence focus on understanding and simulating the cognitive brain at multiple scales as well as its applications to brain-inspired intelligent systems. The main research focus on Brain-inspired Intelligence includes but not limited to neural computation and cognitive brain modeling, neuromorphic computing systems, Brain-inspired information processing, and neural robotics.','Brain-inspired Intelligence is a long term strategic scientific program proposed by Institute of Automation, Chinese Academy of Sciences (CASIA). It is based on the vision of the institute which emphasize the trend on the evolution from Automation to Information Technology, and ultimately to Intelligence Science. Brain-inspired Intelligence is the grand challenge for achieving Human-level Artificial Intelligence. The efforts on Brain-inspired Intelligence focus on understanding and simulating the cognitive brain at multiple scales as well as its applications to brain-inspired intelligent systems. The main research focus on Brain-inspired Intelligence includes but not limited to neural computation and cognitive brain modeling, neuromorphic computing systems, Brain-inspired information processing, and neural robotics.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.ia.cas.cn/rd/201412/t20141202_132383.html',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','f70c1f38e498e28015aa1e40217c031328de743ab6d1f8f4f92b9dd8c5d77426','c18c962d6f68af8a6f94a5eb34f79b147cf94a341e18363e866bef55caffbf48',1,1,1,1 FROM sources WHERE root_url='http://english.ia.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
