INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-A61F151EAF2D9E12B68D','research',NULL,'Humanized Antibody QX007N Shows Promise for Treating IL-33-Driven Airway Inflammation----Institute of Biophysics, Chinese Academy of Sciences','http://english.ibp.cas.cn/research_23463/Research_progress/202609/t20260916_1200511.html',NULL,'Institute of Biophysics',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:09:15.408Z','institutional_primary','en','On September 18, 2026, a research team led by Prof. FENG Wei at the Institute of Biophysics of the Chinese Academy of Sciences, in collaboration with QX Biopharmaceuticals, published a research article in Structure. The study identified QX007N, a humanized monoclonal antibody that targets IL-33 and effectively inhibits its biological activity, and further uncovered how the antibody interferes with IL-33 receptor signaling.','On September 18, 2026, a research team led by Prof. FENG Wei at the Institute of Biophysics of the Chinese Academy of Sciences, in collaboration with QX Biopharmaceuticals, published a research article in Structure. The study identified QX007N, a humanized monoclonal antibody that targets IL-33 and effectively inhibits its biological activity, and further uncovered how the antibody interferes with IL-33 receptor signaling.',NULL,NULL,NULL,NULL,NULL,'10.1016/j.str.2026.08.012','10.1016/j.str.2026.08.012',NULL,'free','