INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-6A28E5601733B8231375','research',NULL,'Researchers Develop Kinetic Decoupling–Recoupling Strategy for Selective Conversion of Polyethylene to Ethylene and Propylene----Institute of Chemistry, Chinese Academy of Sciences','http://english.ic.cas.cn/News2016/Events2016/202511/t20251126_1133402.html',NULL,'Institute of Chemistry',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:09:37.565Z','institutional_primary','en','Prof. HAN Buxing and LIN Longfei ’s group at the Institute of Chemistry, Chinese Academy of Sciences, in collaboration with Beijing Normal University and Peking University, developed a kinetic decoupling–recoupling (KDRC) strategy that enables the conversion of PE to ethylene and propylene with a yield of 79%.','Prof. HAN Buxing and LIN Longfei ’s group at the Institute of Chemistry, Chinese Academy of Sciences, in collaboration with Beijing Normal University and Peking University, developed a kinetic decoupling–recoupling (KDRC) strategy that enables the conversion of PE to ethylene and propylene with a yield of 79%.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.ic.cas.cn/News2016/Events2016/202511/t20251126_1133402.html',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','e6d529182868e12caed6848bebd115c3e430b6512e409bb69b89e2b1561ec263','6a28e5601733b8231375e07e4fd1abdde5b7ecdd1c81d3de2f090cb48b74cbe2',1,1,1,1 FROM sources WHERE root_url='http://english.ic.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
