INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-40D9E8CAC5612BDA089E','research',NULL,'Researchers Develop Nanopore Platform for Time-Resolved Monitoring of Catecholamine Metabolism----Institute of Chemistry, Chinese Academy of Sciences','http://english.ic.cas.cn/News2016/Events2016/202609/t20260921_1200977.html',NULL,'Institute of Chemistry',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:09:37.570Z','institutional_primary','en','Catecholamines, including dopamine, noradrenaline (also known as norepinephrine), and adrenaline (also known as epinephrine), are essential neurotransmitters and hormones that regulate neural and endocrine functions. Disruption of their biosynthesis is associated with a broad range of neurological, psychiatric, and metabolic disorders. However, conventional analytical methods often lack the temporal resolution and sensitivity required to dynamically track multiple metabolites throughout an entire enzymatic pathway. Existing nanopore sensing approaches have also largely focused on individual analytes, making real-time monitoring of a complete metabolic cascade particularly challenging.','Catecholamines, including dopamine, noradrenaline (also known as norepinephrine), and adrenaline (also known as epinephrine), are essential neurotransmitters and hormones that regulate neural and endocrine functions. Disruption of their biosynthesis is associated with a broad range of neurological, psychiatric, and metabolic disorders. However, conventional analytical methods often lack the temporal resolution and sensitivity required to dynamically track multiple metabolites throughout an entire enzymatic pathway. Existing nanopore sensing approaches have also largely focused on individual analytes, making real-time monitoring of a complete metabolic cascade particularly challenging.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.ic.cas.cn/News2016/Events2016/202609/t20260921_1200977.html',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','649d4610985b59f9bd8cb4503af72377b614148a7049200b799694eae48ad0da','40d9e8cac5612bda089ebe2a1dda1020124c9ead7965286d3fb7f31dc88b6f9d',1,1,1,1 FROM sources WHERE root_url='http://english.ic.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
