INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-7E80301DC46121EF1472','research',NULL,'Researchers Develop Photonic Crystal Based Biochips for Rapid and Sensitive Detection of Biomarkers----ICCAS','http://english.ic.cas.cn/News2016/Events2016/202509/t20250916_1054858.html',NULL,'Institute of Chemistry',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:09:37.362Z','institutional_primary','en','Prof. SONG Yanlin and Prof. SU Meng''s group at the Institute of Chemistry, Chinese Academy of Sciences (ICCAS), developed a printing platform to fabricate PC(Photonic crystals) biochips for POCT(Point-of-care testing), with a production capacity of up to 2,700 chips per hour using a single printer.','Prof. SONG Yanlin and Prof. SU Meng''s group at the Institute of Chemistry, Chinese Academy of Sciences (ICCAS), developed a printing platform to fabricate PC(Photonic crystals) biochips for POCT(Point-of-care testing), with a production capacity of up to 2,700 chips per hour using a single printer.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.ic.cas.cn/News2016/Events2016/202509/t20250916_1054858.html',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','d1f262170cfadcc21234fafa9b9e51d15c7f7bd91ed808ca2aef9bece8bfc331','7e80301dc46121ef14723d8f6e98edcbfde14009a4e4a8276bd32053e525a9a2',1,1,1,1 FROM sources WHERE root_url='http://english.ic.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
