INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-4615E5784D3858281E16','research',NULL,'Researchers Develop Surface Diffusion Engineering of a 2D Perovskite Layer for Efficient Perovskite Photovoltaics----ICCAS','http://english.ic.cas.cn/News2016/Events2016/202509/t20250916_1054875.html',NULL,'Institute of Chemistry',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:09:35.629Z','institutional_primary','en','Prof. SONG Yanlin and Prof. WANG Yang’s group at the Institute of Chemistry, Chinese Academy of Sciences, and Prof. ZHOU Huanping from Peking university, has developed a method to improve the performance and stability of perovskite solar cells (PSCs)---novel surface diffusion engineering technique. This method could fabricate phase-pure 2D perovskite passivation layers with precisely controlled structure at the interface between the light-absorbing layer and the charge transport layer.','Prof. SONG Yanlin and Prof. WANG Yang’s group at the Institute of Chemistry, Chinese Academy of Sciences, and Prof. ZHOU Huanping from Peking university, has developed a method to improve the performance and stability of perovskite solar cells (PSCs)---novel surface diffusion engineering technique. This method could fabricate phase-pure 2D perovskite passivation layers with precisely controlled structure at the interface between the light-absorbing layer and the charge transport layer.',