INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-FC7CE6469B910256F21A','research',NULL,'Advanced Aeronautics and Astronautics Propulsion Laboratory--Institute of Engineering Thermophysics, Chinese Academy of Sciences','http://english.iet.cas.cn/research_22384/laboratory/AdvancedAeronauticsandAstronauticsPropulsionLaboratory_39954/',NULL,'Institute of Engineering Thermophysics','author,中国科学院计算机网络信息中心','China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:09:58.763Z','institutional_primary','en','The Institute of Engineering Thermophysics (IET) originated from the Power Laboratory of the Chinese Academy of Sciences (CAS) founded by Academician WU Chung-hua in 1956. At present, it has developed into a research institute combining Dynamic & Electric Engineering and Energy Science & Technology in strategic advanced technology. Since its establishment, the institute has made many remarkable achievements including winning national second prizes, and more than 40 CAS or ministerial second/above second prizes. It has also won more than 50 national, CAS or ministerial third-level prizes.','The Institute of Engineering Thermophysics (IET) originated from the Power Laboratory of the Chinese Academy of Sciences (CAS) founded by Academician WU Chung-hua in 1956. At present, it has developed into a research institute combining Dynamic & Electric Engineering and Energy Science & Technology in strategic advanced technology. Since its establishment, the institute has made many remarkable achievements including winning national second prizes, and more than 40 CAS or ministerial second/above second prizes. It has also won more than 50 national, CAS or ministerial third-level prizes.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.iet.cas.cn/research_22384/laboratory/AdvancedAeronauticsandAstronauticsPropulsionLaboratory_39954/',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','ad27a2c0b65d259ca34e164969830093e4e3aba0e5024d23ddcaf375b2d89190','fc7ce6469b910256f21a2a72e0b272b7175b7afb3f56b3b6bb30325c0e5c262b',1,1,1,1 FROM sources WHERE root_url='http://english.iet.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
