INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-70DFBE63DD30485A477D','research',NULL,'Open positions in Mineral Deposit Studies----Institute of Geochemistry Chinese Academy of Sciences','http://english.gyig.cas.cn/ju/202210/t20221024_322179.html',NULL,'Institute of Geochemistry',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:10:02.251Z','institutional_primary','en','Two ore deposit research groups, one in the Institute of Geochemistry (Chinese Academy of Sciences, Guiyang) and the other in The University of Geosciences (Wuhan), both led by Professor Mei-Fu Zhou, have multiple post-doctoral research positions available in Mineral Deposit studies. We are seeking highly motivated, enthusiastic, and hard-working scientists to pursue research on a variety of ore deposits. We expect the candidates to have field and laboratory skills in magmatic or surficial processes-related deposits. Applicants who have a good background in biology or numerical modeling are also welcome. Successful applicants must have good interpersonal skills and be willing to work in close collaboration with other scientists of our group.','Two ore deposit research groups, one in the Institute of Geochemistry (Chinese Academy of Sciences, Guiyang) and the other in The University of Geosciences (Wuhan), both led by Professor Mei-Fu Zhou, have multiple post-doctoral research positions available in Mineral Deposit studies. We are seeking highly motivated, enthusiastic, and hard-working scientists to pursue research on a variety of ore deposits. We expect the candidates to have field and laboratory skills in magmatic or surficial processes-related deposits. Applicants who have a good background in biology or numerical modeling are also welcome. Successful applicants must have good interpersonal skills and be willing to work in close collaboration with other scientists of our group.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.gyig.cas.cn/ju/202210/t20221024_322179.html',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','1ad0e8b9f5d1ca1812fe5250736a2d0014f4b2398305e0d20a404c19c5a32021','70dfbe63dd30485a477d84f81be4baa18cb5b0a1b3f05cc10950ca7d7b5a9bc5',1,1,1,1 FROM sources WHERE root_url='http://english.gyig.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
