INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-6714546FCF0165978ADA','research',NULL,'Theoretical Mineral Physics Postdoctoral Position Available at Institute of Geochemistry, Chinese Academy of Sciences----Institute of Geochemistry Chinese Academy of Sciences','http://english.gyig.cas.cn/ju/202211/t20221114_323486.html',NULL,'Institute of Geochemistry',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:10:02.424Z','institutional_primary','en','We are looking for one or two postdoctoral research associates to join the research group of Feiwu Zhang and Joshua Muir located at the Institute of Geochemistry, Chinese Academy of Sciences (IGCAS) in Guiyang China. This researcher would be required to investigate various problems of the deep Earth using atomistic simulations. Our current research is diverse and includes the simulation of the elastic effects of volatiles in the mantle and light elements in the core, the thermodynamic effect of heterogeneities on lower mantle mixing, the simulation of grain boundaries for the partitioning of light elements and the formation of critical ores.','We are looking for one or two postdoctoral research associates to join the research group of Feiwu Zhang and Joshua Muir located at the Institute of Geochemistry, Chinese Academy of Sciences (IGCAS) in Guiyang China. This researcher would be required to investigate various problems of the deep Earth using atomistic simulations. Our current research is diverse and includes the simulation of the elastic effects of volatiles in the mantle and light elements in the core, the thermodynamic effect of heterogeneities on lower mantle mixing, the simulation of grain boundaries for the partitioning of light elements and the formation of critical ores.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.gyig.cas.cn/ju/202211/t20221114_323486.html',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','46c82cfbba4ff6f4146d13c04ea27b5d51150655811836d52351bcd5085ef097','6714546fcf0165978ada94cde67977ab38b21fabe0bc77ff9a9046185b5c800d',1,1,1,1 FROM sources WHERE root_url='http://english.gyig.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'theoretical mineral physics postdoctoral position available at institute of geochemistry chinese academy of sciences----institute of geochemistry chinese academy of sciences we are looking for one or two postdoctoral research associates to join the research group of feiwu zhang and joshua muir located at the institute of geochemistry chinese academy of sciences igcas in guiyang china. this researcher would be required to investigate various problems of the deep earth using atomistic simulations. our current research is diverse and includes the simulation of the elastic effects of volatiles in the mantle and light elements in the core the thermodynamic effect of heterogeneities on lower mantle mixing the simulation of grain boundaries for the partitioning of light elements and the formation of critical ores. research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='6714546fcf0165978ada94cde67977ab38b21fabe0bc77ff9a9046185b5c800d' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
