INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-AB68DA151D67F07E998B','research',NULL,'Center for Ore Resources----INSTITUTE OF GEOLOGY AND GEOPHYSICS, CHINESE ACADEMY OF SCIENCES','http://english.igg.cas.cn/rh/rd/Center_OR/',NULL,'Institute of Geology and Geophysics',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:10:03.043Z','institutional_primary','en','The Center addresses scientific frontiers in ore-forming theory and the strategic needs for national mineral resources. By integrating the advantages of geological and geochemical disciplines, it focus on strategic minerals, including rare earth elements, rare metals, precious metals, and commodity metals. The Center investigates ore-forming tectonic backgrounds and environments, reveals the activation, migration and enrichment processes of ore-forming element, develops new ore-forming theories, and creates innovative exploration and evaluation methods, providing scientific and technological support for national resource security.','The Center addresses scientific frontiers in ore-forming theory and the strategic needs for national mineral resources. By integrating the advantages of geological and geochemical disciplines, it focus on strategic minerals, including rare earth elements, rare metals, precious metals, and commodity metals. The Center investigates ore-forming tectonic backgrounds and environments, reveals the activation, migration and enrichment processes of ore-forming element, develops new ore-forming theories, and creates innovative exploration and evaluation methods, providing scientific and technological support for national resource security.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.igg.cas.cn/rh/rd/Center_OR/',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','55f6349d8891e55c09231e3b386d08cb0c3252a32040b317920bdd5008c04d7f','ab68da151d67f07e998bbbcdf68294d40d7e208b8e2e2eff1d5c826f2d35ccb3',1,1,1,1 FROM sources WHERE root_url='http://english.igg.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
