INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-9484820A32A4EF815DEB','research',NULL,'Center for Past Environment Change and Carbon Cycle----INSTITUTE OF GEOLOGY AND GEOPHYSICS, CHINESE ACADEMY OF SCIENCES','http://english.igg.cas.cn/rh/rd/Center_PECCC/',NULL,'Institute of Geology and Geophysics',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:10:03.434Z','institutional_primary','en','General Introduction: The Center aims to advance understanding of environmental changes and carbon cycles during Cenozoic and earlier periods, through interdisciplinary studies on loess, wind-blown red earth, lake deposits, marine sediments, speleothems, tree rings and archaeological remains. The Center investigates the formation and evolution of environmental systems in East Asian and globally, and their dynamic linkages to the global changes. The Center also explores relationships between environmental changes and human activities while clarifying interactions between the lithosphere, hydrosphere, atmosphere, and biosphere. These efforts contribute to the development of “Integration of Earth''s Sphere Dynamic Processes”, a new Earth Science theory. The Center supports national strategic priorities by providing scientific evidence to achieve "dual carbon" goals, tackle climate change, an','General Introduction: The Center aims to advance understanding of environmental changes and carbon cycles during Cenozoic and earlier periods, through interdisciplinary studies on loess, wind-blown red earth, lake deposits, marine sediments, speleothems, tree rings and archaeological remains. The Center investigates the formation and evolution of environmental systems in East Asian and globally, and their dynamic linkages to the global changes. The Center also explores relationships between environmental changes and human activities while clarifying interactions between the lithosphere, hydrosphere, atmosphere, and biosphere. These efforts contribute to the development of “Integration of Earth''s Sphere Dynamic Processes”, a new Earth Science theory. The Center supports national strategic priorities by providing scientific evidence to achieve "dual carbon" goals, tackle climate change, an',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.igg.cas.cn/rh/rd/Center_PECCC/',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','484e00afc3fd3e1546a5ab49b65d09f1794eeee5a20733a6587898e3e8bd1b91','9484820a32a4ef815deb0e06efd4fe512f653f9ea3146c51cc09b97c4c0c9845',1,1,1,1 FROM sources WHERE root_url='http://english.igg.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
