INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-F4BA8D4E173D9C5EAFEF','research',NULL,'Int''l Cooperation News----INSTITUTE OF GEOLOGY AND GEOPHYSICS, CHINESE ACADEMY OF SCIENCES','http://english.igg.cas.cn/ns/icn/202511/t20251117_1115863.html',NULL,'Institute of Geology and Geophysics',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:10:02.635Z','institutional_primary','en','From October 10 to 18, the National Natural Science Foundation of China’s major research program "Tethys Geodynamic System" carried out a seven-day geological investigation in the Nepal Himalaya, in collaboration with the team led by Academician Bishal N. Upreti of Tribhuvan University, Nepal. The expedition was headed by Academician WU Fuyuan of IGGCAS, and brought together 25 experts from Peking University, the Chinese Academy of Geological Sciences, and other institutions. This represents the largest overseas cooperative scientific expedition organized by the program in recent years.','From October 10 to 18, the National Natural Science Foundation of China’s major research program "Tethys Geodynamic System" carried out a seven-day geological investigation in the Nepal Himalaya, in collaboration with the team led by Academician Bishal N. Upreti of Tribhuvan University, Nepal. The expedition was headed by Academician WU Fuyuan of IGGCAS, and brought together 25 experts from Peking University, the Chinese Academy of Geological Sciences, and other institutions. This represents the largest overseas cooperative scientific expedition organized by the program in recent years.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.igg.cas.cn/ns/icn/202511/t20251117_1115863.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','c1d27aa4784effdfbfceb56bec7d60b11046c9f9c7bffad1b368b2988e643019','f4ba8d4e173d9c5eafef4b905e0f6282ffd74eef54c60951734307166aad4688',1,1,1,1 FROM sources WHERE root_url='http://english.igg.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
