INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-1FB4C084CB3DEB455CE0','research',NULL,'Int''l Cooperation News----INSTITUTE OF GEOLOGY AND GEOPHYSICS, CHINESE ACADEMY OF SCIENCES','http://english.igg.cas.cn/ns/icn/202510/t20251028_1095020.html',NULL,'Institute of Geology and Geophysics',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:10:02.826Z','institutional_primary','en','BEIJING, Oct 22 nd 2025 – The Annual Assembly of the China-South America Joint Research Center (CSAJC), hosted by IGGCAS, achieved remarkable success from October 6 to 19, 2025. The assembly comprised three major events: a joint field excursion titled "A Glimpse into the Geology of the Khondalite Belt of the North China Craton: From Basement to Basins" held from October 7 to 16 across Inner Mongolia, Ningxia, Beijing, and Tianjin; an international workshop on "Correlation between Chinese (East Asian) and South American Cratons" on October 17; and a Forum on October 18 in Beijing.','BEIJING, Oct 22 nd 2025 – The Annual Assembly of the China-South America Joint Research Center (CSAJC), hosted by IGGCAS, achieved remarkable success from October 6 to 19, 2025. The assembly comprised three major events: a joint field excursion titled "A Glimpse into the Geology of the Khondalite Belt of the North China Craton: From Basement to Basins" held from October 7 to 16 across Inner Mongolia, Ningxia, Beijing, and Tianjin; an international workshop on "Correlation between Chinese (East Asian) and South American Cratons" on October 17; and a Forum on October 18 in Beijing.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.igg.cas.cn/ns/icn/202510/t20251028_1095020.html',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','30c5094cf4ebd220f21d326d02b7070edbbfca240d29b07dbc428952203b9ff6','1fb4c084cb3deb455ce0ad325d3c8daf5fe38d7a4573cfe3c39fefdc77e0a066',1,1,1,1 FROM sources WHERE root_url='http://english.igg.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
