INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-D3700DC7CC0546DFB583','research',NULL,'Research News----INSTITUTE OF GEOLOGY AND GEOPHYSICS, CHINESE ACADEMY OF SCIENCES','http://english.igg.cas.cn/rh/rp/202604/t20260408_1155379.html',NULL,'Institute of Geology and Geophysics',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:10:03.497Z','institutional_primary','en','Supereruptions are extremely large volcanic eruptions that eject more than 1,000 cubic kilometers of magma, rock and ash. They are among the most hazardous geological events on Earth and have profound impacts on the environment, climate, and human society. For this reason, understanding the subsurface processes behind supereruptions is essential for improving volcanic hazard assessments and mitigating risks.','Supereruptions are extremely large volcanic eruptions that eject more than 1,000 cubic kilometers of magma, rock and ash. They are among the most hazardous geological events on Earth and have profound impacts on the environment, climate, and human society. For this reason, understanding the subsurface processes behind supereruptions is essential for improving volcanic hazard assessments and mitigating risks.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.igg.cas.cn/rh/rp/202604/t20260408_1155379.html',NULL,1,'B','V2',200,'V2: institution certifiée 3/3,