INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-87D8A9F26324E86325D7','research',NULL,'Upcoming Events----INSTITUTE OF GEOLOGY AND GEOPHYSICS, CHINESE ACADEMY OF SCIENCES','http://english.igg.cas.cn/ns/ue/202608/t20260825_1188809.html',NULL,'Institute of Geology and Geophysics',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:10:03.227Z','institutional_primary','en','After decades of lunar exploration, lunar samples have become the largest treasure returned by human beings, with unlimited potential to disclose the secrets of the Earth-Moon system. So far, lunar samples have been collected by the USA’s Apollo-11, 12, 14, 15, 16, 17 missions, the Soviet Union’s Luna 16, 20, 24 missions, and China’s Chang’e-5, 6 missions, and recovered as meteorites. The recent acquisition of the Chang’e-5 samples from the Procellarum KREEP Terrance, the Chang’e-6 samples from the South Pole Aitken basin, and the recent opening of NASA’s Apollo samples in the Apollo Next Generation Sample Analysis program bring a new era of lunar science that is likely to solve the most significant questions that have remained since the Apollo era.','After decades of lunar exploration, lunar samples have become the largest treasure returned by human beings, with unlimited potential to disclose the secrets of the Earth-Moon system. So far, lunar samples have been collected by the USA’s Apollo-11, 12, 14, 15, 16, 17 missions, the Soviet Union’s Luna 16, 20, 24 missions, and China’s Chang’e-5, 6 missions, and recovered as meteorites. The recent acquisition of the Chang’e-5 samples from the Procellarum KREEP Terrance, the Chang’e-6 samples from the South Pole Aitken basin, and the recent opening of NASA’s Apollo samples in the Apollo Next Generation Sample Analysis program bring a new era of lunar science that is likely to solve the most significant questions that have remained since the Apollo era.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.igg.cas.cn/ns/ue/202608/t20260825_1188809.html',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','9fe5edcfe3cd6160cd69aeae0f1bc83909e00fc3c493e4b81d9a2196a8091fc5','87d8a9f26324e86325d774d902a12221775934891ae01bb49e540e675f33e951',1,1,1,1 FROM sources WHERE root_url='http://english.igg.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
