INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-6BCACC76589BBB3EAC8B','research',NULL,'Scientists Reveal Niobium’s Dual Role in Stabilizing High-Silicon Austenitic Steel for Lead-Cooled Fast Reactors----Institute of Metal Research, Chinese Academy of Sciences','http://english.imr.cas.cn/research/researchprogress/202609/t20260921_1201021.html',NULL,'Institute of Metal Research',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:10:28.366Z','institutional_primary','en','Scientists from the Institute of Metal Research, Chinese Academy of Sciences (IMR, CAS), in collaboration with researchers from The Hong Kong Polytechnic University, have clarified the dual regulatory role of niobium (Nb) in the microstructural stability of high-silicon austenitic stainless steel, offering a new strategy to suppress austenite decomposition during long-term service at elevated temperatures.','Scientists from the Institute of Metal Research, Chinese Academy of Sciences (IMR, CAS), in collaboration with researchers from The Hong Kong Polytechnic University, have clarified the dual regulatory role of niobium (Nb) in the microstructural stability of high-silicon austenitic stainless steel, offering a new strategy to suppress austenite decomposition during long-term service at elevated temperatures.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.imr.cas.cn/research/researchprogress/202609/t20260921_1201021.html',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','b051532827389c3633fbedbb047fc2b9fb711a972e604dc0dc7f07c40e2645f8','6bcacc76589bbb3eac8b55a757995cfd110b6e1d0b869584242cf62cb2670d04',1,1,1,1 FROM sources WHERE root_url='http://english.imr.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
