INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-4B0CAEA43E76C8E28042','research',NULL,'The 3rd International Conference on Computational Design and Simulation of Materials (CDSM2026) Held in Shenyang----Institute of Metal Research, Chinese Academy of Sciences','http://english.imr.cas.cn/news/newsrelease/202609/t20260907_1192668.html',NULL,'Institute of Metal Research',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T23:10:27.632Z','institutional_primary','en','The 3rd International Conference on Computational Design and Simulation of Materials (CDSM2026) was successfully held in Shenyang, Liaoning Province, from August 28 to 30. The conference was co-sponsored by The Chinese Society for Metals (CSM), the Institute of Metal Research, Chinese Academy of Sciences (IMR, CAS), and The Minerals, Metals & Materials Society (TMS). The conference was co-chaired by Academician LI Dianzhong (IMR, CAS) and Dr. Song-Mao (Simon) Liang (TMS representative). Academician LI Yiyi, Chair of the 1st CDSM, was invited to attend. The conference was also supported by the Central Iron and Steel Research Institute, Northeastern University, and the Shenyang Association for Science and Technology.','The 3rd International Conference on Computational Design and Simulation of Materials (CDSM2026) was successfully held in Shenyang, Liaoning Province, from August 28 to 30. The conference was co-sponsored by The Chinese Society for Metals (CSM), the Institute of Metal Research, Chinese Academy of Sciences (IMR, CAS), and The Minerals, Metals & Materials Society (TMS). The conference was co-chaired by Academician LI Dianzhong (IMR, CAS) and Dr. Song-Mao (Simon) Liang (TMS representative). Academician LI Yiyi, Chair of the 1st CDSM, was invited to attend. The conference was also supported by the Central Iron and Steel Research Institute, Northeastern University, and the Shenyang Association for Science and Technology.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.imr.cas.cn/news/newsrelease/202609/t20260907_1192668.html',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','69238fa1cf1fd95e71d419606ba078362985f6698f8d31588bf2eaba8bad7be1','4b0caea43e76c8e280422eeeea45304679a8ec0c7cd8ebcb3a860625dca5ff5d',1,1,1,1 FROM sources WHERE root_url='http://english.imr.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
