INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-6380EBED3DEA4761A043','research',NULL,'Institut des sciences du vivant Frédéric-Joliot - Les bébés doués de conscience ?','https://www.cea.fr/drf/Pages/Actualites/En-direct-des-labos/2013/Les-bebes-doues-de-conscience-.aspx',NULL,'CEA',NULL,'France','Europe','public_research','2013-4-19',NULL,'2026-10-03T23:06:19.783Z','institutional_primary','fr','Les bébés ont longtemps été considérés comme ayant des comportements principalement automatiques qui ne s’accompagnent pas d’une expérience subjective consciente. Et pourtant : des chercheurs du CEA-I2BM et du CNRS montrent que les nourrissons possèdent dès 5 mois une forme de conscience similaire à celle des adultes.','Les bébés ont longtemps été considérés comme ayant des comportements principalement automatiques qui ne s’accompagnent pas d’une expérience subjective consciente. Et pourtant : des chercheurs du CEA-I2BM et du CNRS montrent que les nourrissons possèdent dès 5 mois une forme de conscience similaire à celle des adultes.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.cea.fr/drf/Pages/Actualites/En-direct-des-labos/2013/Les-bebes-doues-de-conscience-.aspx',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','a31cc6b8abd5984d5399f6bfa17c9a00fb61aa75c75bce7c4909e16a3a5fa542','6380ebed3dea4761a043af29f6304b99fcd5d26ee5b75ee3449e219460c0f37d',1,1,1,1 FROM sources WHERE root_url='https://www.cea.fr/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
