INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-441AE818A765B0502EB1','applied_research',NULL,'Current VDMA Study - Fraunhofer AISEC','https://www.aisec.fraunhofer.de/en/media/press-releases/2025/current-vdma-study-.html',NULL,'Applied and Integrated Security',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-03T23:04:52.730Z','institutional_primary','en','The mechanical and plant engineering sector has shown significant progress in defending against cyber-risks. According to a current study titled Industrial Security, conducted by the German Mechanical Engineering Industry Association (VDMA) in cooperation with the Fraunhofer Institute for Applied and Integrated Security AISEC, more and more companies are investing in digital protective measures. In spite of these improvements, cyberattacks continue to cause considerable damage, with harm totaling in the nine figures. Further action is needed, especially for smaller enterprises. Social engineering and phishing represent the biggest threat to companies, followed by human error and sabotage.','The mechanical and plant engineering sector has shown significant progress in defending against cyber-risks. According to a current study titled Industrial Security, conducted by the German Mechanical Engineering Industry Association (VDMA) in cooperation with the Fraunhofer Institute for Applied and Integrated Security AISEC, more and more companies are investing in digital protective measures. In spite of these improvements, cyberattacks continue to cause considerable damage, with harm totaling in the nine figures. Further action is needed, especially for smaller enterprises. Social engineering and phishing represent the biggest threat to companies, followed by human error and sabotage.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.aisec.fraunhofer.de/en/media/press-releases/2025/current-vdma-study-.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','76e50c891ef5f8d6b857d04a8b520fdf27c1967917e805358c7c645c0b97f84d','441ae818a765b0502eb1edf2f2549e2661886fad1140f59fd81ca7abb159d051',1,1,1,1 FROM sources WHERE root_url='https://www.aisec.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
