INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-9D37CE365A13DDB5941A','applied_research',NULL,'IPCEI-CIS Project KIbSIS is developing fully automated AI-Based safety acknowledgment for machine tools - Fraunhofer AISEC','https://www.aisec.fraunhofer.de/en/media/press-releases/2026/ipcei-cis-projekt-kibsis-en.html',NULL,'Applied and Integrated Security',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-03T23:04:52.870Z','institutional_primary','en','Imagine a self-organizing factory: safety zones are cleared automatically and cyberattacks remain ineffective. This may sound like science fiction, but the KIbSIS research project is making it come true. As part of an international cooperation with South Korea, partners from the areas of research and business are seeking to develop fully automated AI-based safety acknowledgment for machine tools by 2028. The approach is based on standardized, trustworthy and quantum-secure AI technology.','Imagine a self-organizing factory: safety zones are cleared automatically and cyberattacks remain ineffective. This may sound like science fiction, but the KIbSIS research project is making it come true. As part of an international cooperation with South Korea, partners from the areas of research and business are seeking to develop fully automated AI-based safety acknowledgment for machine tools by 2028. The approach is based on standardized, trustworthy and quantum-secure AI technology.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.aisec.fraunhofer.de/en/media/press-releases/2026/ipcei-cis-projekt-kibsis-en.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','708dc7a21fccdd64fd125087d5060edcf0ea6296794d46e7d508fced1dbd3487','9d37ce365a13ddb5941aaabed0c48b9e51076ea8ae1b50bd57b29c1811b674d1',1,1,1,1 FROM sources WHERE root_url='https://www.aisec.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
