INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-D7B6933E68FD985E55EC','applied_research',NULL,'Research Fab Microelectronics Germany - Fraunhofer AISEC','https://www.aisec.fraunhofer.de/en/about-us/research-fab-microelectronics-germany.html',NULL,'Applied and Integrated Security',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-03T23:04:53.298Z','institutional_primary','en','Fraunhofer AISEC is one of 15 research institutes cooperating within Research Fab Microelectronics Germany (FMD). It has been part of the Fraunhofer Group for Microelectronics since 2016. Fraunhofer AISEC contributes to FMD as an expert in hardware security and trusted electronics. An important contribution in this regard is involvement in the Advanced Packaging and Heterogeneous Integration for Electronic Components and Systems (APECS) pilot line in the context of the EU Chips Act ( -&gt; link to press release ).','Fraunhofer AISEC is one of 15 research institutes cooperating within Research Fab Microelectronics Germany (FMD). It has been part of the Fraunhofer Group for Microelectronics since 2016. Fraunhofer AISEC contributes to FMD as an expert in hardware security and trusted electronics. An important contribution in this regard is involvement in the Advanced Packaging and Heterogeneous Integration for Electronic Components and Systems (APECS) pilot line in the context of the EU Chips Act ( -&gt; link to press release ).',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.aisec.fraunhofer.de/en/about-us/research-fab-microelectronics-germany.html',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','a0cd9ca59587d95d9f3fa493fea3a9d061186747dcdff9ea7132834a6ffa6a27','d7b6933e68fd985e55ece597859fba54153a8bf034d9c34f4d5a1c513162a742',1,1,1,1 FROM sources WHERE root_url='https://www.aisec.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
