INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-E233171780FC40F3B058','applied_research',NULL,'Research Project Provides Court-Proof Methods for Forensic Analysis of AI Systems - Fraunhofer AISEC','https://www.aisec.fraunhofer.de/en/media/press-releases/2025/Forensics-of-Intelligent-Systems.html',NULL,'Applied and Integrated Security',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-03T23:04:52.721Z','institutional_primary','en','The Forensics of Intelligent Systems research project is dedicated to the development of inter-disciplinary approaches to ensuring forensic readiness in the event of manipulation of continuously learning AI systems. The research project is funded by Cyberagentur and realized jointly by Atos, a globally leading enterprise in the field of AI-supported digital transformation, the Fraunhofer Institute for Intelligent Analysis and Information Systems IAIS, the Fraunhofer Institute for Applied and Integrated Security AISEC, the Institut für Internet-Sicherheit (Institute for Internet Security, Westphalian University of Applied Sciences) and the University of Cologne. The project aims to sustainably strengthen cyber security and the rule of law in the digital age.','The Forensics of Intelligent Systems research project is dedicated to the development of inter-disciplinary approaches to ensuring forensic readiness in the event of manipulation of continuously learning AI systems. The research project is funded by Cyberagentur and realized jointly by Atos, a globally leading enterprise in the field of AI-supported digital transformation, the Fraunhofer Institute for Intelligent Analysis and Information Systems IAIS, the Fraunhofer Institute for Applied and Integrated Security AISEC, the Institut für Internet-Sicherheit (Institute for Internet Security, Westphalian University of Applied Sciences) and the University of Cologne. The project aims to sustainably strengthen cyber security and the rule of law in the digital age.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.aisec.fraunhofer.de/en/media/press-releases/2025/Forensics-of-Intelligent-Systems.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','7eef8426c971d93721f7c4457e56ab033995b7d77ad9a93bfaad50a832b7b3f2','e233171780fc40f3b058acb3a8c2f2d4938caa42bc2c549686a20b500a62b5b4',1,1,1,1 FROM sources WHERE root_url='https://www.aisec.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'research project provides court-proof methods for forensic analysis of ai systems - fraunhofer aisec the forensics of intelligent systems research project is dedicated to the development of inter-disciplinary approaches to ensuring forensic readiness in the event of manipulation of continuously learning ai systems. the research project is funded by cyberagentur and realized jointly by atos a globally leading enterprise in the field of ai-supported digital transformation the fraunhofer institute for intelligent analysis and information systems iais the fraunhofer institute for applied and integrated security aisec the institut fur internet-sicherheit institute for internet security westphalian university of applied sciences and the university of cologne. the project aims to sustainably strengthen cyber security and the rule of law in the digital age. applied research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='e233171780fc40f3b058acb3a8c2f2d4938caa42bc2c549686a20b500a62b5b4' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
