INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-F22F262943343D1DEF11','applied_research',NULL,'Collaboration - Fraunhofer FIT','https://www.fit.fraunhofer.de/en/business-areas/data-science-and-artificial-intelligence/process-mining/collaboration.html',NULL,'Applied Information Technology',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-03T23:05:18.763Z','institutional_primary','en','There has been an increasing awareness of the huge potential that process and data science provides for businesses, as witnessed by several success stories as published by the IEEE CIS Task Force on Process Mining . As a result, several software development companies have developed solutions that support and / or integrate process mining oriented analyses. Moreover, some software vendors provide dedicated process mining solutions. However, integration of state-of-the-art techniques, originating from process mining research, are often missing.','There has been an increasing awareness of the huge potential that process and data science provides for businesses, as witnessed by several success stories as published by the IEEE CIS Task Force on Process Mining . As a result, several software development companies have developed solutions that support and / or integrate process mining oriented analyses. Moreover, some software vendors provide dedicated process mining solutions. However, integration of state-of-the-art techniques, originating from process mining research, are often missing.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.fit.fraunhofer.de/en/business-areas/data-science-and-artificial-intelligence/process-mining/collaboration.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','cb6ef0da2501fbb0c441c75482e83d69558a3dbd0a2a0ccdaaea9f88bc7bfee2','f22f262943343d1def11304e0533dae35911a010b6922e45def8d40b9efc4ecf',1,1,1,1 FROM sources WHERE root_url='https://www.fit.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
