INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-7031330B8AC71C6A660C','applied_research',NULL,'Intelligent Data Analytics - Fraunhofer FIT','https://www.fit.fraunhofer.de/en/business-areas/data-science-and-artificial-intelligence/intelligent-data-analytics.html',NULL,'Applied Information Technology',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-03T23:05:17.716Z','institutional_primary','en','Data is a central phenomenon in our digital information society. It effects our production and economic systems and offers enormous potential to positively influence our behavior and environment in society, business and science. Developing new machine learning methods for intelligent data analysis that can automatically extract and access knowledge in data-intensive environments to create economic value and new business opportunities is one of the central goals of the Intelligent Data Analysis research group.','Data is a central phenomenon in our digital information society. It effects our production and economic systems and offers enormous potential to positively influence our behavior and environment in society, business and science. Developing new machine learning methods for intelligent data analysis that can automatically extract and access knowledge in data-intensive environments to create economic value and new business opportunities is one of the central goals of the Intelligent Data Analysis research group.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.fit.fraunhofer.de/en/business-areas/data-science-and-artificial-intelligence/intelligent-data-analytics.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','6594164036750fed1d86bd8553659ad49e9548c11b213b1461756a58a5762069','7031330b8ac71c6a660c233481bd68b88232dce3bb3ff54b984f2d5d402ebaad',1,1,1,1 FROM sources WHERE root_url='https://www.fit.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
