INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-D3B38FF3F17581883209','applied_research',NULL,'Knowledge-Enhanced Large Language Models - Fraunhofer FIT','https://www.fit.fraunhofer.de/en/business-areas/data-science-and-artificial-intelligence/knowledge-enhanced-large-language-models.html',NULL,'Applied Information Technology',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-03T23:05:16.224Z','institutional_primary','en','Large Language Models (LLMs), such as ChatGPT, are a new generation of AI models that are revolutionizing the way we interact with computers. Trained on massive amounts of text data, LLMs can be used to perform a variety of tasks, including question answering, machine translation, text generation, and even code generation. As a result, LLMs are beginning to be used in a variety of real-world applications. For example, they are being used to develop conversational assistants, also known as co-pilots, such as GitHub Copilot and Microsoft 365 Copilot. These co-pilots can help developers write code faster and more efficiently, and they can also be used to generate other creative content, such as marketing copy or blog posts.','Large Language Models (LLMs), such as ChatGPT, are a new generation of AI models that are revolutionizing the way we interact with computers. Trained on massive amounts of text data, LLMs can be used to perform a variety of tasks, including question answering, machine translation, text generation, and even code generation. As a result, LLMs are beginning to be used in a variety of real-world applications. For example, they are being used to develop conversational assistants, also known as co-pilots, such as GitHub Copilot and Microsoft 365 Copilot. These co-pilots can help developers write code faster and more efficiently, and they can also be used to generate other creative content, such as marketing copy or blog posts.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.fit.fraunhofer.de/en/business-areas/data-science-and-artificial-intelligence/knowledge-enhanced-large-language-models.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','13293f85ead46722e1c3948af2181759f2a30e1f464abaa689c254fa875a6d02','d3b38ff3f1758188320966788d216f2c2743bae8a7595cfccdff9d7e005105cf',1,1,1,1 FROM sources WHERE root_url='https://www.fit.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
