INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-D9ABBF7636BDD0BAB75F','applied_research',NULL,'Vital Signs at a Glance without Contact - Fraunhofer IOF','https://www.iof.fraunhofer.de/en/pressrelease/2026/goviscan-2026.html',NULL,'Applied Optics and Precision Engineering',NULL,'Germany','Europe','official_research_institution','2026-09-21T11:16:00Z',NULL,'2026-10-03T23:05:16.775Z','institutional_primary','en','Measuring heart rate, respiratory rate, and oxygen saturation without electrodes on the skin or invasive sensors on the body. This is enabled by goVISCAN: a new, compact sensor developed by Fraunhofer IOF in collaboration with partners in the AMI research alliance. The sensor is now being unveiled for the first time at the W3+ trade show in Jena and the VISION trade show in Stuttgart.','Measuring heart rate, respiratory rate, and oxygen saturation without electrodes on the skin or invasive sensors on the body. This is enabled by goVISCAN: a new, compact sensor developed by Fraunhofer IOF in collaboration with partners in the AMI research alliance. The sensor is now being unveiled for the first time at the W3+ trade show in Jena and the VISION trade show in Stuttgart.',NULL,NULL,NULL,NULL,NULL,'10.1117/12.3099761','10.1117/12.3099761',NULL,'free','primary','not_applicable',NULL,NULL,'https://www.iof.fraunhofer.de/en/pressrelease/2026/goviscan-2026.html',NULL,1,'B','V2',200,'V2: institution cert