INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-510872A116DF10F2DA7A','applied_research',NULL,'A Sustainable Flame Retardant Derived From Corn Steep Liquor - Fraunhofer IAP','https://www.iap.fraunhofer.de/en/press_releases/2026/a-sustainable-flame-retardant-derived-from-corn-steep-liquor.html',NULL,'Applied Polymer Research',NULL,'Germany','Europe','official_research_institution','2026-09-01T08:00:00Z',NULL,'2026-10-03T23:05:35.710Z','institutional_primary','en','Halogenated flame retardants raise environmental concerns and are considered harmful to human health. As a result, researchers have been searching for alternatives for many years. Fraunhofer researchers are focusing on sustainable phosphorus-based raw materials derived from corn steep liquor. The phytic acid it contains is an excellent natural flame retardant for biomaterials.','Halogenated flame retardants raise environmental concerns and are considered harmful to human health. As a result, researchers have been searching for alternatives for many years. Fraunhofer researchers are focusing on sustainable phosphorus-based raw materials derived from corn steep liquor. The phytic acid it contains is an excellent natural flame retardant for biomaterials.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.iap.fraunhofer.de/en/press_releases/2026/a-sustainable-flame-retardant-derived-from-corn-steep-liquor.html',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','faf6908d6fa67d05df1d429d3ad83aad03b6e9d48951fd6b3367bacd52511b98','510872a116df10f2da7a3beaac390715237b4e1ce19e8d8cab8f0e3726eea111',1,1,1,1 FROM sources WHERE root_url='https://www.iap.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
