INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-C9863DD2C4E3D598E55A','applied_research',NULL,'100-V-technology - Fraunhofer IAF','https://www.iaf.fraunhofer.de/en/media-library/press-releases/100-V-Technology.html',NULL,'Applied Solid State Physics',NULL,'Germany','Europe','official_research_institution','2020-03-24T10:00:00Z',NULL,'2026-10-03T23:05:36.073Z','institutional_primary','en','Researchers at the Fraunhofer Institute for Applied Solid State Physics IAF have succeeded in significantly increasing the output power of their GaN-based high-frequency transistors for the frequency range from 1 - 2 GHz: They have been able to double the operating voltage of the components from 50 volts to 100 volts, thus achieving a power-added efficiency of 77.3 percent. With this technology, it is now possible to develop highly efficient amplifiers with even higher power, as required for applications in the fields of plasma generation, industrial heating, communication and radar technologies.','Researchers at the Fraunhofer Institute for Applied Solid State Physics IAF have succeeded in significantly increasing the output power of their GaN-based high-frequency transistors for the frequency range from 1 - 2 GHz: They have been able to double the operating voltage of the components from 50 volts to 100 volts, thus achieving a power-added efficiency of 77.3 percent. With this technology, it is now possible to develop highly efficient amplifiers with even higher power, as required for applications in the fields of plasma generation, industrial heating, communication and radar technologies.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.iaf.fraunhofer.de/en/media-library/press-releases/100-V-Technology.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','ab2954f7856d5d6474e809e8260dab96e6912a00b3596bbac429b25f9dd0e633','c9863dd2c4e3d598e55a7a3412fc42469e90ef557ea485891e89ee3934582deb',1,1,1,1 FROM sources WHERE root_url='https://www.iaf.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
