INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-C701FE92E47524E17CCB','applied_research',NULL,'EU-project joins forces towards the era of scalable control technology for quantum processors - Fraunhofer IAF','https://www.iaf.fraunhofer.de/en/media-library/press-releases/ARCITC-scalable-quantum-processors.html',NULL,'Applied Solid State Physics',NULL,'Germany','Europe','official_research_institution','2024-08-12T08:00:00Z',NULL,'2026-10-03T23:05:35.698Z','institutional_primary','en','Project ARCTIC brings together 36 international partners from industry, academia and leading RTOs to establish a complete and comprehensive European supply chain and develop scalable, reliable, innovative control infrastructure for cryogenic quantum processors.','Project ARCTIC brings together 36 international partners from industry, academia and leading RTOs to establish a complete and comprehensive European supply chain and develop scalable, reliable, innovative control infrastructure for cryogenic quantum processors.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.iaf.fraunhofer.de/en/media-library/press-releases/ARCITC-scalable-quantum-processors.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','32b54dc4685b2b6bb7db028e772ca25121b9add488dd2acecb1deb585b