INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-EB77F48451B332CE63AB','applied_research',NULL,'European project aims to scale up quantum computing technology - Fraunhofer IAF','https://www.iaf.fraunhofer.de/en/media-library/press-releases/european-project-aims-to-scale-up-quantum-computing-technology.html',NULL,'Applied Solid State Physics',NULL,'Germany','Europe','official_research_institution','2020-09-16T08:45:00Z',NULL,'2026-10-03T23:05:35.702Z','institutional_primary','en','The Fraunhofer Institute for Applied Solid State Physics IAF has partnered up with the start-up “Twenty-One Semiconductors” (21s) from Stuttgart to bring their unique laser concept from lab to practice. Having become a member of the high-tech incubator “FMD-Space” – initiated by the Research Fab Microelectronics Germany (FMD) – 21s has gained access to Europe’s largest machine park in the field of micro- and nanoelectronics. As a part of the FMD, Fraunhofer IAF is supporting the young company with its expertise in the field of semiconductor laser technologies. They are working together to develop a novel, efficient and compact membrane laser module.','The Fraunhofer Institute for Applied Solid State Physics IAF has partnered up with the start-up “Twenty-One Semiconductors” (21s) from Stuttgart to bring their unique laser concept from lab to practice. Having become a member of the high-tech incubator “FMD-Space” – initiated by the Research Fab Microelectronics Germany (FMD) – 21s has gained access to Europe’s largest machine park in the field of micro- and nanoelectronics. As a part of the FMD, Fraunhofer IAF is supporting the young company with its expertise in the field of semiconductor laser technologies. They are working together to develop a novel, efficient and compact membrane laser module.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.iaf.fraunhofer.de/en/media-library/press-releases/european-project-aims-to-scale-up-quantum-computing-technology.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','c7e929b75287ad7a169853c0cd113562f409c9c4f55da3d8560d77d6b5d79af6','eb77f48451b332ce63ab55a237fd7a07d047fcbd00350b2e4e645126721cef45',1,1,1,1 FROM sources WHERE root_url='https://www.iaf.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
