INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-2939AF7CA78BF1DF2898','applied_research',NULL,'A-DRZ project launch - Fraunhofer FKIE','https://www.fkie.fraunhofer.de/en/press-releases/a-drz_project_launch.html',NULL,'Communication, Information Processing and Ergonomics',NULL,'Germany','Europe','official_research_institution','2018-11-12T23:00:00Z',NULL,'2026-10-03T23:06:52.320Z','institutional_primary','en','The Fraunhofer Institute for Communication, Information Processing and Ergonomics FKIE is one of 13 partners from the fields of emergency response, research and industry involved in the establishment of the German Rescue Robotics Center (A-DRZ) in Dortmund. The project, funded with 11.9 million euros from the Federal Ministry of Education and Research (BMBF), will officially kick off on 6 December. The mission of the new center is to promote the use of robots in rescue scenarios that pose excessive risks to emergency personnel.','The Fraunhofer Institute for Communication, Information Processing and Ergonomics FKIE is one of 13 partners from the fields of emergency response, research and industry involved in the establishment of the German Rescue Robotics Center (A-DRZ) in Dortmund. The project, funded with 11.9 million euros from the Federal Ministry of Education and Research (BMBF), will officially kick off on 6 December. The mission of the new center is to promote the use of robots in rescue scenarios that pose excessive risks to emergency personnel.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.fkie.fraunhofer.de/en/press-releases/a-drz_project_launch.html',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','f9fc686e8c30cc7b39e0fd1e25dac173c7007d0b6ffff39d5ede28b356aa7b12','2939af7ca78bf1df2898d3f36f920b9cea58d779f7ca933d421ff62c63e528e8',1,1,1,1 FROM sources WHERE root_url='https://www.fkie.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'a-drz project launch - fraunhofer fkie the fraunhofer institute for communication information processing and ergonomics fkie is one of 13 partners from the fields of emergency response research and industry involved in the establishment of the german rescue robotics center a-drz in dortmund. the project funded with 11.9 million euros from the federal ministry of education and research bmbf will officially kick off on 6 december. the mission of the new center is to promote the use of robots in rescue scenarios that pose excessive risks to emergency personnel. applied research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='2939af7ca78bf1df2898d3f36f920b9cea58d779f7ca933d421ff62c63e528e8' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-BEE9CCA527C6D9F37A0C','applied_research',NULL,'Aviation - Fraunhofer FKIE','https://www.fkie.fraunhofer.de/en/press-releases/Aviation_research-news_07-2023.html',NULL,'Communication, Information Processing and Ergonomics',NULL,'Germany','Europe','official_research_institution','2023-07-03T09:00:00Z',NULL,'2026-10-03T23:06:52.324Z','institutional_primary','en','Maintenance of modern aircraft is a complex process. The use of AR smart glasses with 3D information visualization should make repair and maintenance work easier for aircraft mechanics. Virtual elements such as instructions, displays and technical tools can be operated by way of gesture, voice and gaze control. With the help of augmented reality systems, researchers at the Fraunhofer Institute for Communication, Information Processing and Ergonomics FKIE have developed concepts and solutions for maintaining the Airbus A400M.','Maintenance of modern aircraft is a complex process. The use of AR smart glasses with 3D information visualization should make repair and maintenance work easier for aircraft mechanics. Virtual elements such as instructions, displays and technical tools can be operated by way of gesture, voice and gaze control. With the help of augmented reality systems, researchers at the Fraunhofer Institute for Communication, Information Processing and Ergonomics FKIE have developed concepts and solutions for maintaining the Airbus A400M.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.fkie.fraunhofer.de/en/press-releases/Aviation_research-news_07-2023.html',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','da1b427ecb1babcf3d71dc093b52efffdec4eec549f13a22cced49f3879773fc','bee9cca527c6d9f37a0cd071763f87cb982e0af46e44a76bf7a07f588ecfbd13',1,1,1,1 FROM sources WHERE root_url='https://www.fkie.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
