INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-FF51865A05E670D0222A','applied_research',NULL,'Drones for search and rescue in disaster areas - Fraunhofer FKIE','https://www.fkie.fraunhofer.de/en/press-releases/GlobalReportingOfDroneResearch.html',NULL,'Communication, Information Processing and Ergonomics',NULL,'Germany','Europe','official_research_institution','2021-07-06T07:00:00Z',NULL,'2026-10-03T23:06:51.940Z','institutional_primary','en','Drones equipped with microphone arrays will help rescue workers in disaster areas to find and rescue survivors more quickly. They can detect cries for help and signals from buried victims from the air and simultaneously pinpoint their location. Macarena Varela, a scientist at the Fraunhofer Institute for Communication, Information Processing and Ergonomics FKIE, has developed this technology to help victims in situations where every second counts.','Drones equipped with microphone arrays will help rescue workers in disaster areas to find and rescue survivors more quickly. They can detect cries for help and signals from buried victims from the air and simultaneously pinpoint their location. Macarena Varela, a scientist at the Fraunhofer Institute for Communication, Information Processing and Ergonomics FKIE, has developed this technology to help victims in situations where every second counts.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.fkie.fraunhofer.de/en/press-releases/GlobalReportingOfDroneResearch.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','d9e0578bc5495e7106c6a36329ecf8ddd5a7cc8a762103fc1dd384ac4ef939e8','ff51865a05e670d0222aaf62dfee302546e4fefd4ed35132a4bf5a2309190c21',1,1,1,1 FROM sources WHERE root_url='https://www.fkie.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
