INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-2AE633FCDB4C9386C4EC','applied_research',NULL,'AI Bias and Fairness - Fraunhofer MEVIS','https://www.mevis.fraunhofer.de/en/research-and-technologies/research-cluster/data-and-ai-readiness/ai-bias-and-fairness.html',NULL,'Digital Medicine',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-03T23:08:40.570Z','institutional_primary','en','© Fraunhofer MEVIS / chest X-ray images courtesy of the NIH CXR8 database Does Your AI Work for Every Patient? Medical AI systems are increasingly used to support clinical decisions, from triaging radiology findings to predicting patient risk. But a system that performs well on average may still fail systematically for specific patient groups: patients of different sexes or genders, elderly or younger patients, individuals of different skin tones or ethnic backgrounds, or patients from underrepresented clinical sites. These disparities are a fundamental challenge to the safe and equitable deployment of AI in healthcare; addressing requires an intentional and methodologically rigorous approach.','© Fraunhofer MEVIS / chest X-ray images courtesy of the NIH CXR8 database Does Your AI Work for Every Patient? Medical AI systems are increasingly used to support clinical decisions, from triaging radiology findings to predicting patient risk. But a system that performs well on average may still fail systematically for specific patient groups: patients of different sexes or genders, elderly or younger patients, individuals of different skin tones or ethnic backgrounds, or patients from underrepresented clinical sites. These disparities are a fundamental challenge to the safe and equitable deployment of AI in healthcare; addressing requires an intentional and methodologically rigorous approach.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.mevis.fraunhofer.de/en/research-and-technologies/research-cluster/data-and-ai-readiness/ai-bias-and-fairness.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','0cbd1de0c32e4007c57253a2d8fbff7cb2936f358d19e40784d3e4e7d72c9285','2ae633fcdb4c9386c4ec37e7a1445720f93c0fe1c5ea0ef8d77bdda8c9d9442d',1,1,1,1 FROM sources WHERE root_url='https://www.mevis.fraunhofer.de/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
