INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-448297DA8B5D8130FEB9','applied_research',NULL,'Reliable Medical Image Data for the German National Cohort – Fraunhofer MEVIS Delivers Digital Infrastructure for Germany’s Largest Health Study - Fraunhofer MEVIS','https://www.mevis.fraunhofer.de/en/press-and-scicom/press-release/reliable-medical-image-data-for-the-german-national-cohort--frau.html',NULL,'Digital Medicine',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-03T23:08:39.955Z','institutional_primary','en','© Fraunhofer MEVIS NAKO-Viewer in the MR lab managed by Fraunhofer MEVIS and the University of Bremen June marks the beginning of the National Cohort (NAKO), a long-term study of 200,000 subjects, the broadest of its kind in Germany to date. Gathering MRI data of up to 30,000 subjects is central to the study. These images help scientists gain valuable insight into the formation and development of diseases. As a partner in this research project, the Fraunhofer Institute for Medical Image Computing MEVIS in Bremen is responsible for making images directly available in reliably high quality – a significant prerequisite for the success of the study. The software system from MEVIS facilitates the participating radiologists’ access to the image data. This allows experts to notice abnormalities in the scans quickly and reliably and notify test subjects of serious problems promptly.','© Fraunhofer MEVIS NAKO-Viewer in the MR lab managed by Fraunhofer MEVIS and the University of Bremen June marks the beginning of the National Cohort (NAKO), a long-term study of 200,000 subjects, the broadest of its kind in Germany to date. Gathering MRI data of up to 30,000 subjects is central to the study. These images help scientists gain valuable insight into the formation and development of diseases. As a partner in this research project, the Fraunhofer Institute for Medical Image Computing MEVIS in Bremen is responsible for making images directly available in reliably high quality – a significant prerequisite for the success of the study. The software system from MEVIS facilitates the participating radiologists’ access to the image data. This allows experts to notice abnormalities in the scans quickly and reliably and notify test subjects of serious problems promptly.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.mevis.fraunhofer.de/en/press-and-scicom/press-release/reliable-medical-image-data-for-the-german-national-cohort--frau.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','5e382d2c259b62d33eee346a76068453b51c7aa182c40542d23a7a078a4eed90','448297da8b5d8130feb9468426552c693c0dda1e711479590c35099ea291e154',1,1,1,1 FROM sources WHERE root_url='https://www.mevis.fraunhofer.de/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'reliable medical image data for the german national cohort fraunhofer mevis delivers digital infrastructure for germany s largest health study - fraunhofer mevis fraunhofer mevis nako-viewer in the mr lab managed by fraunhofer mevis and the university of bremen june marks the beginning of the national cohort nako a long-term study of 200 000 subjects the broadest of its kind in germany to date. gathering mri data of up to 30 000 subjects is central to the study. these images help scientists gain valuable insight into the formation and development of diseases. as a partner in this research project the fraunhofer institute for medical image computing mevis in bremen is responsible for making images directly available in reliably high quality a significant prerequisite for the success of the study. the software system from mevis facilitates the participating radiologists access to the image data. this allows experts to notice abnormalities in the scans quickly and reliably and notify test subjects of serious problems promptly. applied research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='448297da8b5d8130feb9468426552c693c0dda1e711479590c35099ea291e154' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
