INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-61DF9E06E5CCC889ED11','applied_research',NULL,'Bonding and Deep RIE - Fraunhofer ENAS','https://www.enas.fraunhofer.de/en/Business_Units/Process,_Device_and_Packaging_Technology/MEMS_Technology_platforms/Bonding_and_Deep_RIE.html',NULL,'Electronic Nano Systems',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-03T23:08:58.066Z','institutional_primary','en','This technology platform based on wafer compounds with pre-structured cavity enables in particular the fabrication of electrostatic actuators and capacitive sensors with high aspect ratios (AR up to 40) for the precise detection of very small movements in up to 3 dimensions. This concept provides many degrees of freedom in the designs.','This technology platform based on wafer compounds with pre-structured cavity enables in particular the fabrication of electrostatic actuators and capacitive sensors with high aspect ratios (AR up to 40) for the precise detection of very small movements in up to 3 dimensions. This concept provides many degrees of freedom in the designs.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.enas.fraunhofer.de/en/Business_Units/Process,_Device_and_Packaging_Technology/MEMS_Technology_platforms/Bonding_and_Deep_RIE.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','1cd8db3d439101ceec39ea5b46b104a7c4781f8eb0924b99239b5ac80a270be2','61df9e06e5ccc889ed112c9e173ec5d1ab8ed0c09b39ec0e4832179d2f13c51e',1,1,1,1 FROM sources WHERE root_url='https://www.enas.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
