INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-181EAE80E6C684AD9E9F','applied_research',NULL,'Integratable Spectral Sensing in Multi-Reactor Technology - Result Interpretation Using Neural Networks - Fraunhofer ENAS','https://www.enas.fraunhofer.de/en/Business_Units/test-and-reliability-solutions/Data-based-Methods/Integratable_spectral_sensing_in_multi-reactor_technology-result_interpretation_using_neural_networks.html',NULL,'Electronic Nano Systems',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-03T23:08:57.887Z','institutional_primary','en','© Fraunhofer ENAS Sampling and data aquisition via spectrometer. © Fraunhofer ENAS Aggregation and provision of spectral data. © Fraunhofer ENAS Training of specific neural network and result evaluation. Multi-reactor systems are well established, especially in pharmaceutical research and catalysis. They are characterized by a high degree of automation and parallelization, which ensures high efficiency. However, targeted manipulation of processes requires more precise knowledge about the concentration of the reaction participants during the reaction progression. Here, NIR spectroscopy represents a suitable method. As part of a research project, we integrated a miniaturized spectrometer module into the system architecture of a multi-reactor system. We qualified it for various hydrogenation reactions. We then used machine learning and neural network methods to calibrate the obtained spectr','© Fraunhofer ENAS Sampling and data aquisition via spectrometer. © Fraunhofer ENAS Aggregation and provision of spectral data. © Fraunhofer ENAS Training of specific neural network and result evaluation. Multi-reactor systems are well established, especially in pharmaceutical research and catalysis. They are characterized by a high degree of automation and parallelization, which ensures high efficiency. However, targeted manipulation of processes requires more precise knowledge about the concentration of the reaction participants during the reaction progression. Here, NIR spectroscopy represents a suitable method. As part of a research project, we integrated a miniaturized spectrometer module into the system architecture of a multi-reactor system. We qualified it for various hydrogenation reactions. We then used machine learning and neural network methods to calibrate the obtained spectr',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.enas.fraunhofer.de/en/Business_Units/test-and-reliability-solutions/Data-based-Methods/Integratable_spectral_sensing_in_multi-reactor_technology-result_interpretation_using_neural_networks.html',NULL,4,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','183c582a7d02eba03d396bd6c0869fc9148de2134511b887b63fb0bb1222185f','181eae80e6c684ad9e9f83787137e74edeb1a7d8f28939be6844480502047d12',1,1,1,1 FROM sources WHERE root_url='https://www.enas.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'integratable spectral sensing in multi-reactor technology - result interpretation using neural networks - fraunhofer enas fraunhofer enas sampling and data aquisition via spectrometer. fraunhofer enas aggregation and provision of spectral data. fraunhofer enas training of specific neural network and result evaluation. multi-reactor systems are well established especially in pharmaceutical research and catalysis. they are characterized by a high degree of automation and parallelization which ensures high efficiency. however targeted manipulation of processes requires more precise knowledge about the concentration of the reaction participants during the reaction progression. here nir spectroscopy represents a suitable method. as part of a research project we integrated a miniaturized spectrometer module into the system architecture of a multi-reactor system. we qualified it for various hydrogenation reactions. we then used machine learning and neural network methods to calibrate the obtained spectr applied research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='181eae80e6c684ad9e9f83787137e74edeb1a7d8f28939be6844480502047d12' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
