INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-B91002423717A0622E42','applied_research',NULL,'Piezoelectric Microsystems - Fraunhofer ENAS','https://www.enas.fraunhofer.de/en/Business_Units/Process,_Device_and_Packaging_Technology/MEMS_Technology_platforms/Piezoelectric_Microsystems.html',NULL,'Electronic Nano Systems',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-03T23:08:58.243Z','institutional_primary','en','This technology platform is based on the utilization of piezoelectric aluminum nitride (AlN) for the actuation of moving structures or for the detection of very small movements. A sputtering process was developed and optimized for the deposition of piezoelectric AlN. The deposition takes place directly on (111)-Si or on a special electrode material. Another electrode is structured above the AlN and enables the electrical control of the elements. In contrast to conventionally used lead-zirconium titanate (PZT), this technology is C-MOS compatible, as deposition and structuring can be realized with conventional systems for aluminum-based BEOL technologies.','This technology platform is based on the utilization of piezoelectric aluminum nitride (AlN) for the actuation of moving structures or for the detection of very small movements. A sputtering process was developed and optimized for the deposition of piezoelectric AlN. The deposition takes place directly on (111)-Si or on a special electrode material. Another electrode is structured above the AlN and enables the electrical control of the elements. In contrast to conventionally used lead-zirconium titanate (PZT), this technology is C-MOS compatible, as deposition and structuring can be realized with conventional systems for aluminum-based BEOL technologies.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.enas.fraunhofer.de/en/Business_Units/Process,_Device_and_Packaging_Technology/MEMS_Technology_platforms/Piezoelectric_Microsystems.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','c105748c163cb53e194b1e56763175c573a729af2089edba6151e3b599e4f0f9','b91002423717a0622e4270db9c614d21d9414e27c3179415403f378b35e5289f',1,1,1,1 FROM sources WHERE root_url='https://www.enas.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
