INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-BB935F47EA01AC36B85C','applied_research',NULL,'Networks, Energy & Process Engineering - Fraunhofer IEG','https://www.ieg.fraunhofer.de/en/research-topics/networks-energy-process-engineering.html',NULL,'Energy Infrastructures and Geotechnologies',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-03T23:09:36.370Z','institutional_primary','en','In unserer Abteilung »Energietechnik und Infrastrukturen« in Bochum mit den Abteilungen »Verfahrenstechnik«, »Infrastrukturen Wärme und Kälte«, »Energiesysteme«, »Upstream Processing«, und »Gebäudeintegration« erforschen und entwickeln wir Verbundlösungen zur Nutzung thermischer Energie aus Gewinnungs- und Speichersystemen.','In unserer Abteilung »Energietechnik und Infrastrukturen« in Bochum mit den Abteilungen »Verfahrenstechnik«, »Infrastrukturen Wärme und Kälte«, »Energiesysteme«, »Upstream Processing«, und »Gebäudeintegration« erforschen und entwickeln wir Verbundlösungen zur Nutzung thermischer Energie aus Gewinnungs- und Speichersystemen.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.ieg.fraunhofer.de/en/research-topics/networks-energy-process-engineering.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','ab5969cb8185