INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-A0C6F04A83B448E3CD6D','applied_research',NULL,'Post-Mining-Exploitation - Fraunhofer IEG','https://www.ieg.fraunhofer.de/en/research-topics/georesources-and-geothermal-energy/post-mining-exploitation.html',NULL,'Energy Infrastructures and Geotechnologies',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-03T23:09:36.374Z','institutional_primary','en','Our competence center for post-mining utilization demonstrates how former mining infrastructures can become reliable sources of renewable heating and cooling. With more than ten years of experience, we analyze and model flooded mine workings, assess their potential as seasonal energy storage systems, and develop economically viable utilization concepts for municipalities, public utilities, and industry. Through digital mine representations, high‑resolution 3D models, and robust feasibility studies, we provide a reliable foundation for planning and implementation. In regions with a mining heritage, we are your partner for a safe and sustainable heat supply of the future.','Our competence center for post-mining utilization demonstrates how former mining infrastructures can become reliable sources of renewable heating and cooling. With more than ten years of experience, we analyze and model flooded mine workings, assess their potential as seasonal energy storage systems, and develop economically viable utilization concepts for municipalities, public utilities, and industry. Through digital mine representations, high‑resolution 3D models, and robust feasibility studies, we provide a reliable foundation for planning and implementation. In regions with a mining heritage, we are your partner for a safe and sustainable heat supply of the future.',NULL,NULL,NULL,NULL,NULL,'10.21268/20250804-0','10.21268/20250804-0',NULL,'free','primary','not_applicable',NULL,NULL,'https://www.ieg.fraunhofer.de/en/research-topics/georesources-and-geothermal-energy/post-mining-exploitation.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','a4a4ca5a88b06b34749060ed1c25a3ce1d5ad551b035768b6d6fca8d37dd601c','a0c6f04a83b448e3cd6de82a76d44d06277645a6811334bf3f1c2814d0be3ba3',1,1,1,1 FROM sources WHERE root_url='https://www.ieg.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
