INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-7784F25E7A628F4F5896','applied_research',NULL,'Process Engineering - Fraunhofer IEG','https://www.ieg.fraunhofer.de/en/research-topics/networks-energy-process-engineering/process-engineering.html',NULL,'Energy Infrastructures and Geotechnologies',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-03T23:09:36.363Z','institutional_primary','en','Our competence centre for process engineering develops plants from simple test benches to large-scale plants and from the initial idea to operational optimisation. We support the planning and implementation of both material and thermodynamic processes in plant design, design and component dimensioning, and simulations of individual components as well as complete plants. In addition, we design and test the control of complex systems, accompany plant construction and commissioning, and monitor operation and convert the results into operational optimisation. We always work closely with customers and project partners and transfer theoretical, scientific findings into practice. Thermal processes in industry and in neighbourhoods face the same challenge as the energy system as a whole: becoming more sustainable and integrating new energy sources. To this end, process engineers at the Fraunhofe','Our competence centre for process engineering develops plants from simple test benches to large-scale plants and from the initial idea to operational optimisation. We support the planning and implementation of both material and thermodynamic processes in plant design, design and component dimensioning, and simulations of individual components as well as complete plants. In addition, we design and test the control of complex systems, accompany plant construction and commissioning, and monitor operation and convert the results into operational optimisation. We always work closely with customers and project partners and transfer theoretical, scientific findings into practice. Thermal processes in industry and in neighbourhoods face the same challenge as the energy system as a whole: becoming more sustainable and integrating new energy sources. To this end, process engineers at the Fraunhofe',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.ieg.fraunhofer.de/en/research-topics/networks-energy-process-engineering/process-engineering.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','2c1a8bf88f3b635d37ad5391f8b6c3b2d215b46cad3bf7b75765f5b50d54008e','7784f25e7a628f4f58965aa593a89c811e761bcbeedef45504b5944a59fea582',1,1,1,1 FROM sources WHERE root_url='https://www.ieg.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
