INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-C043E26E4ABB779BD216','applied_research',NULL,'CEADS paves the way for secure agricultural data exchange in Europe - Fraunhofer IESE','https://www.iese.fraunhofer.de/en/media/press/pm_2025_07_09_ceads.html',NULL,'Experimental Software Engineering',NULL,'Germany','Europe','official_research_institution','2025-07-09T12:15:00Z',NULL,'2026-10-03T23:10:27.543Z','institutional_primary','en','The Common European Agricultural Data Space (CEADS), an initiative to create a common European agricultural data space, was launched on April 1, 2025. The 36 project partners from 15 countries came together for a three-day kick-off event in Ghent (Belgium) at the beginning of May. The project, which is funded by the European Commission through the “Digital Europe” program, is coordinated by the Flanders Research Institute for Agriculture, Fisheries and Food (ILVO). Over the next three years, the partners will work on enabling the secure, sovereign and trustworthy use of data across the entire agricultural and food value chain, including public administration. With the start of the project, the Fraunhofer Institute for Experimental Software Engineering IESE is also taking on a central role as a technology partner.','The Common European Agricultural Data Space (CEADS), an initiative to create a common European agricultural data space, was launched on April 1, 2025. The 36 project partners from 15 countries came together for a three-day kick-off event in Ghent (Belgium) at the beginning of May. The project, which is funded by the European Commission through the “Digital Europe” program, is coordinated by the Flanders Research Institute for Agriculture, Fisheries and Food (ILVO). Over the next three years, the partners will work on enabling the secure, sovereign and trustworthy use of data across the entire agricultural and food value chain, including public administration. With the start of the project, the Fraunhofer Institute for Experimental Software Engineering IESE is also taking on a central role as a technology partner.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.iese.fraunhofer.de/en/media/press/pm_2025_07_09_ceads.html',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','0768fd9526149787e54f5971e98df4c0f7d82cbf07929b4f27f75fbddea87543','c043e26e4abb779bd2165a5f793e7939581cfbe9037083222cc873c4cdfce92c',1,1,1,1 FROM sources WHERE root_url='https://www.iese.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'ceads paves the way for secure agricultural data exchange in europe - fraunhofer iese the common european agricultural data space ceads an initiative to create a common european agricultural data space was launched on april 1 2025. the 36 project partners from 15 countries came together for a three-day kick-off event in ghent belgium at the beginning of may. the project which is funded by the european commission through the digital europe program is coordinated by the flanders research institute for agriculture fisheries and food ilvo . over the next three years the partners will work on enabling the secure sovereign and trustworthy use of data across the entire agricultural and food value chain including public administration. with the start of the project the fraunhofer institute for experimental software engineering iese is also taking on a central role as a technology partner. applied research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='c043e26e4abb779bd2165a5f793e7939581cfbe9037083222cc873c4cdfce92c' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
