INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-8105557161EA05AEC5E8','applied_research',NULL,'Fraunhofer research project “FHIR-Starter” develops AI-based software for structuring medical data - Fraunhofer IESE','https://www.iese.fraunhofer.de/en/media/press/pm_2025_02_20-fhir-starter.html',NULL,'Experimental Software Engineering',NULL,'Germany','Europe','official_research_institution','2025-02-19T23:00:00Z',NULL,'2026-10-03T23:10:26.996Z','institutional_primary','en','Improving healthcare, relieving the burden on medical professionals and advancing research in Germany: These are the goals of the three-year research project “FHIR-Starter” starting in February 2025. The project focuses on the development of a software service that is able to automatically structure medical data using large language models (LLMs). To this end, the Fraunhofer Institute for Experimental Software Engineering IESE is cooperating with Prof. Sylvia Thun''s working group at the Berlin Institute for Health Research at Charité and the AI company Insiders Technologies from Kaiserslautern. Fraunhofer IESE is the consortium leader. The project is being funded by the Federal Ministry for Economic Affairs and Energy as part of the “Generative AI for SMEs” innovation competition with 1.64 million euros. Translated with DeepL.com (free version)','Improving healthcare, relieving the burden on medical professionals and advancing research in Germany: These are the goals of the three-year research project “FHIR-Starter” starting in February 2025. The project focuses on the development of a software service that is able to automatically structure medical data using large language models (LLMs). To this end, the Fraunhofer Institute for Experimental Software Engineering IESE is cooperating with Prof. Sylvia Thun''s working group at the Berlin Institute for Health Research at Charité and the AI company Insiders Technologies from Kaiserslautern. Fraunhofer IESE is the consortium leader. The project is being funded by the Federal Ministry for Economic Affairs and Energy as part of the “Generative AI for SMEs” innovation competition with 1.64 million euros. Translated with DeepL.com (free version)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.iese.fraunhofer.de/en/media/press/pm_2025_02_20-fhir-starter.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','ac0281929526731c784cc6b1e07d084b13c306fae1a9e2366017dbf8ce7d99ed','8105557161ea05aec5e810d138a14142ae4eadc67e2388cf93c0131cb8e994b2',1,1,1,1 FROM sources WHERE root_url='https://www.iese.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'fraunhofer research project fhir-starter develops ai-based software for structuring medical data - fraunhofer iese improving healthcare relieving the burden on medical professionals and advancing research in germany these are the goals of the three-year research project fhir-starter starting in february 2025. the project focuses on the development of a software service that is able to automatically structure medical data using large language models llms . to this end the fraunhofer institute for experimental software engineering iese is cooperating with prof. sylvia thun s working group at the berlin institute for health research at charite and the ai company insiders technologies from kaiserslautern. fraunhofer iese is the consortium leader. the project is being funded by the federal ministry for economic affairs and energy as part of the generative ai for smes innovation competition with 1.64 million euros. translated with deepl.com free version applied research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='8105557161ea05aec5e810d138a14142ae4eadc67e2388cf93c0131cb8e994b2' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
