INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-9DBB95519D07636ED3D3','applied_research',NULL,'New Research Project Aims to Finally Make Data Privacy Preferences Easy to Manage - Fraunhofer IESE','https://www.iese.fraunhofer.de/en/media/press/pm_2026_08_18_project_kickoff_ddpp.html',NULL,'Experimental Software Engineering',NULL,'Germany','Europe','official_research_institution','2026-08-18T13:00:00Z',NULL,'2026-10-03T23:10:27.714Z','institutional_primary','en','With the kickoff meeting on August 17, 2026, the ddpp (Decentralized Data Privacy Protocol) project officially began its collaboration. The goal of the project is to make it significantly easier for people to manage their privacy settings and to strengthen their digital sovereignty. To this end, the research project is developing an open web protocol designed to enable users to manage their privacy preferences across different services from a location of their choosing. The project has been running since July 1, 2026, for a period of three years. The Fraunhofer Institute for Experimental Software Engineering IESE is the consortium leader, and Saarland University is a project partner.','With the kickoff meeting on August 17, 2026, the ddpp (Decentralized Data Privacy Protocol) project officially began its collaboration. The goal of the project is to make it significantly easier for people to manage their privacy settings and to strengthen their digital sovereignty. To this end, the research project is developing an open web protocol designed to enable users to manage their privacy preferences across different services from a location of their choosing. The project has been running since July 1, 2026, for a period of three years. The Fraunhofer Institute for Experimental Software Engineering IESE is the consortium leader, and Saarland University is a project partner.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.iese.fraunhofer.de/en/media/press/pm_2026_08_18_project_kickoff_ddpp.html',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','b50f56cd1e036af631d1fe018f8a1d36b694c7e07e70fc2337787dac4550903f','9dbb95519d07636ed3d313794692e6e5ebac227db14fdace0564fe064ed8c72c',1,1,1,1 FROM sources WHERE root_url='https://www.iese.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'new research project aims to finally make data privacy preferences easy to manage - fraunhofer iese with the kickoff meeting on august 17 2026 the ddpp decentralized data privacy protocol project officially began its collaboration. the goal of the project is to make it significantly easier for people to manage their privacy settings and to strengthen their digital sovereignty. to this end the research project is developing an open web protocol designed to enable users to manage their privacy preferences across different services from a location of their choosing. the project has been running since july 1 2026 for a period of three years. the fraunhofer institute for experimental software engineering iese is the consortium leader and saarland university is a project partner. applied research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='9dbb95519d07636ed3d313794692e6e5ebac227db14fdace0564fe064ed8c72c' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
