INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-CD306BA0497EBC18B52A','earth_science',NULL,'Bomb-produced radiocarbon across the South Pacific Gyre — A new record from American Samoa with utility for fisheries science | U.S. Geological Survey','https://www.usgs.gov/publications/bomb-produced-radiocarbon-across-south-pacific-gyre-a-new-record-american-samoa',NULL,'3-D CT Core Imaging Laboratory',NULL,'United States','North America','official_research_institution','2021-06-10T23:09:00Z',NULL,'2026-10-03T23:05:07.078Z','institutional_primary','en','Coral skeletal structures can provide a robust record of nuclear bomb produced 14C with valuable insight into air-sea exchange processes and water movement with applications to fisheries science. To expand these records in the South Pacific, a coral core from Tutuila Island, American Samoa was dated with density band counting covering a 59-yr period (1953–2012). Seasonal signals in elemental','Coral skeletal structures can provide a robust record of nuclear bomb produced 14C with valuable insight into air-sea exchange processes and water movement with applications to fisheries science. To expand these records in the South Pacific, a coral core from Tutuila Island, American Samoa was dated with density band counting covering a 59-yr period (1953–2012). Seasonal signals in elemental',NULL,NULL,NULL,NULL,NULL,'10.1017/RDC.2021.51','10.1017/RDC.2021.51',NULL,'free','primary','not_applicable',NULL,NULL,'https://www.usgs.gov/publications/bomb-produced-radiocarbon-across-south-pacific-gyre-a-new-record-american-samoa',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','1031579c9da527cc974e732b8eea4ef7aa9238a89d18b19218dc7002830cc042','cd306ba0497ebc18b52a22e581f04d05518ef4cd65590043df7e6895136377b1',1,1,1,1 FROM sources WHERE root_url='https://www.usgs.gov/labs/santa-cruz-core-scanning-laboratory' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
