INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-A727E517726CB3C19C37','earth_science',NULL,'Cascadia Subduction Zone Marine Geohazards | U.S. Geological Survey','https://www.usgs.gov/centers/pcmsc/science/cascadia-subduction-zone-marine-geohazards',NULL,'3-D CT Core Imaging Laboratory',NULL,'United States','North America','official_research_institution','2022-07-05T21:39:21Z',NULL,'2026-10-03T23:05:14.764Z','institutional_primary','en','Societal Issue: Uncertainty related to rupture extent, slip distribution, and recurrence of past subduction megathrust earthquakes in the Pacific Northwest (northern CA, OR, WA, and southern BC) leads to ambiguity in earthquake and tsunami hazard assessments and hinders our ability to prepare for future events.','Societal Issue: Uncertainty related to rupture extent, slip distribution, and recurrence of past subduction megathrust earthquakes in the Pacific Northwest (northern CA, OR, WA, and southern BC) leads to ambiguity in earthquake and tsunami hazard assessments and hinders our ability to prepare for future events.',NULL,NULL,NULL,NULL,NULL,'10.5066/P9MYL7WJ','10.5066/P9MYL7WJ',NULL,'free','primary','not_applicable',NULL,NULL,'https://www.usgs.gov/centers/pcmsc/science/cascadia-subduction-zone-marine-geohazards',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus