INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-98A5E4F30A8AF1A2F86D','earth_science',NULL,'Developing a USGS Digital Coral Growth Archive using Rotating X-Ray Computerized Tomography​ - The ACTS Project | U.S. Geological Survey','https://www.usgs.gov/programs/cmhrp/science/developing-a-usgs-digital-coral-growth-archive-using-rotating-x-ray',NULL,'3-D CT Core Imaging Laboratory',NULL,'United States','North America','official_research_institution','2022-06-28T00:00:00Z',NULL,'2026-10-03T23:05:01.345Z','institutional_primary','en','The Archival Computed Tomography Scanning Project (ACTS) currently develops the USGS Coral Core Archive, housed at the Pacific and St. Petersburg Coastal and Marine Science Centers, that contains approximately 500 coral reef cores from U.S. jurisdictions worldwide. This archive, is one of the largest coral archives in the world and provides historical context for coral-reef science studies, including crucial data for modern coral calcification rates, reef erosion, and impacts on reef-lined coasts. The archive also offers unique opportunities to test hypotheses about environmental controls on coral growth and erosion.','The Archival Computed Tomography Scanning Project (ACTS) currently develops the USGS Coral Core Archive, housed at the Pacific and St. Petersburg Coastal and Marine Science Centers, that contains approximately 500 coral reef cores from U.S. jurisdictions worldwide. This archive, is one of the largest coral archives in the world and provides historical context for coral-reef science studies, including crucial data for modern coral calcification rates, reef erosion, and impacts on reef-lined coasts. The archive also offers unique opportunities to test hypotheses about environmental controls on coral growth and erosion.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.usgs.gov/programs/cmhrp/science/developing-a-usgs-digital-coral-growth-archive-using-rotating-x-ray',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','bd3cb3b63428ca8f37974079e629f0db6f3407f0caeedb1da9921b8266f70086','98a5e4f30a8af1a2f86d9542b7347422e2135fed15ab5ad18172ed4ac261a3b2',1,1,1,1 FROM sources WHERE root_url='https://www.usgs.gov/labs/santa-cruz-core-scanning-laboratory' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'developing a usgs digital coral growth archive using rotating x-ray computerized tomography - the acts project u.s. geological survey the archival computed tomography scanning project acts currently develops the usgs coral core archive housed at the pacific and st. petersburg coastal and marine science centers that contains approximately 500 coral reef cores from u.s. jurisdictions worldwide. this archive is one of the largest coral archives in the world and provides historical context for coral-reef science studies including crucial data for modern coral calcification rates reef erosion and impacts on reef-lined coasts. the archive also offers unique opportunities to test hypotheses about environmental controls on coral growth and erosion. earth science',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='98a5e4f30a8af1a2f86d9542b7347422e2135fed15ab5ad18172ed4ac261a3b2' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
