INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-2CE2974FF54D2C4F8BC8','public_higher_education_research',NULL,'AFIT / Autonomy & Navigation Technology (ANT) Center','https://www.afit.edu/ANT/',NULL,'Air Force Institute of Technology-Graduate School of Engineering & Management',NULL,'United States','North America','public_graduate_higher_education_research_source',NULL,NULL,'2026-10-03T23:05:35.476Z','institutional_primary','en','The Autonomy and Navigation Technology (ANT) Center is a forward-looking research center seeking to identify and solve tomorrow''s most challenging navigation and autonomous and cooperative control problems. The ANT Center''s goal is to develop navigation technology that ensures we can navigate anywhere, anytime, using anything. The ANT Center focuses on three research thrusts: autonomous and cooperative systems, non-GPS precision navigation, and robust GPS navigation/NAVWAR. Under Air Force Research Laboratory sponsorship, the ANT Center designed and built a GPS-based relative navigation system that determines cm-level relative positions between two flying aircraft. The Center also developed autonomous formation flight control algorithms and successfully flew the entire system at the USAF Test Pilot School, accomplishing the first fully autonomous precision formation flight appropriate fo','The Autonomy and Navigation Technology (ANT) Center is a forward-looking research center seeking to identify and solve tomorrow''s most challenging navigation and autonomous and cooperative control problems. The ANT Center''s goal is to develop navigation technology that ensures we can navigate anywhere, anytime, using anything. The ANT Center focuses on three research thrusts: autonomous and cooperative systems, non-GPS precision navigation, and robust GPS navigation/NAVWAR. Under Air Force Research Laboratory sponsorship, the ANT Center designed and built a GPS-based relative navigation system that determines cm-level relative positions between two flying aircraft. The Center also developed autonomous formation flight control algorithms and successfully flew the entire system at the USAF Test Pilot School, accomplishing the first fully autonomous precision formation flight appropriate fo',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.afit.edu/ANT/',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','0bd3f551f898ec44194c257841386a33f4dcaa92d4a02605e810026e59be2544','2ce2974ff54d2c4f8bc8cd5e5c9b1876312faef4d95b2f601cdf56b47294bc98',1,1,1,1 FROM sources WHERE root_url='https://www.afit.edu/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
