INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-C0BD18A199EBA83E1B64','public_higher_education_research',NULL,'AFIT / Center for Technical Intelligence Studies and Research (CTISR)','https://www.afit.edu/CTISR/',NULL,'Air Force Institute of Technology-Graduate School of Engineering & Management',NULL,'United States','North America','public_graduate_higher_education_research_source',NULL,NULL,'2026-10-03T23:05:35.486Z','institutional_primary','en','The AFIT Center for Technical Intelligence Studies and Research (CTISR) is focused on Air Force, Space Force, DOD and Intelligence Community&rsquo;s scientific, technical and operational activities through graduate research programs. CTISR brings together cleared faculty across academic departments to solve difficult, multi-disciplinary technical intelligence problems. Several current research projects include: signature measurement; phenomenological understanding; algorithm development for target detection and tracking; battle space combustion characterization; event classification; material identification; dim target detection and tracking; sensor data fusion for TI enhancement; and understanding target signature phenomenology and remote sensing platforms for enhanced exploitation of intelligence data. CTISR is also spearheading a business model which will enable defense contractors an','The AFIT Center for Technical Intelligence Studies and Research (CTISR) is focused on Air Force, Space Force, DOD and Intelligence Community&rsquo;s scientific, technical and operational activities through graduate research programs. CTISR brings together cleared faculty across academic departments to solve difficult, multi-disciplinary technical intelligence problems. Several current research projects include: signature measurement; phenomenological understanding; algorithm development for target detection and tracking; battle space combustion characterization; event classification; material identification; dim target detection and tracking; sensor data fusion for TI enhancement; and understanding target signature phenomenology and remote sensing platforms for enhanced exploitation of intelligence data. CTISR is also spearheading a business model which will enable defense contractors an',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.afit.edu/CTISR/',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','06004bafe693f76c6876ad5cb6595d36370d0d8c1c6a4d944d3080b632d95e62','c0bd18a199eba83e1b64bb617577d9d069b5e34ea6dd5cc16e36d0bb43cedff7',1,1,1,1 FROM sources WHERE root_url='https://www.afit.edu/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
