INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-4BBD4E2D13CE8EA7E599','public_higher_education_research',NULL,'Clery Report - Alabama A&M University','https://www.aamu.edu/campus-life/campus-safety/clery-report.html',NULL,'Alabama A & M University',NULL,'United States','North America','public_graduate_higher_education_research_source',NULL,NULL,'2026-10-03T23:05:37.016Z','institutional_primary','en','The Annual Security and Fire Safety Report is prepared by Alabama A&M University (AAMU) Department of Public Safety (DPS) to comply with the requirements of the Jeanne Clery Disclosure of Campus Security Policy and Crime Statistics Act (Clery Act) and the Higher Education Opportunity Act (HEOA) of the Higher Education Act of 1965. This report combines the AAMU Annual Security Report and Annual Fire Safety Report into one report, as permitted by the Clery Act. The statistical data in this report are obtained from the AAMU Department of Public Safety, Office of Student Affairs, Residential Life, Student Conduct and Community Standards, the Huntsville Police Department, Madison County Sheriffs Office & Madison Police Department.','The Annual Security and Fire Safety Report is prepared by Alabama A&M University (AAMU) Department of Public Safety (DPS) to comply with the requirements of the Jeanne Clery Disclosure of Campus Security Policy and Crime Statistics Act (Clery Act) and the Higher Education Opportunity Act (HEOA) of the Higher Education Act of 1965. This report combines the AAMU Annual Security Report and Annual Fire Safety Report into one report, as permitted by the Clery Act. The statistical data in this report are obtained from the AAMU Department of Public Safety, Office of Student Affairs, Residential Life, Student Conduct and Community Standards, the Huntsville Police Department, Madison County Sheriffs Office & Madison Police Department.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.aamu.edu/campus-life/campus-safety/clery-report.html',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','771ef35317d727b5cfc7880aec709a5354aba0741b3952c0c17097cd2e2b0fa3','4bbd4e2d13ce8ea7e599bcb0a3f371a8aef41d0e12402969a023457897ec3e20',1,1,1,1 FROM sources WHERE root_url='https://www.aamu.edu/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
