INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-1719C9BB40348EDD9676','public_higher_education_research',NULL,'Arizona Promise Program | Arizona Board of Regents','https://www.azregents.edu/programs/arizona-promise-program',NULL,'Arizona Board of Regents',NULL,'United States','North America','public_graduate_higher_education_research_source',NULL,NULL,'2026-10-03T23:06:51.389Z','institutional_primary','en','The Arizona Promise Program is a guaranteed scholarship program for eligible Arizona residents that ensures all tuition and fees are covered at Arizona&#039;s public universities. Arizona&#039;s first statewide financial aid program is making higher education more accessible and affordable for Arizona students and families. The promise scholarship is applied after all other aid, scholarships and grants are used. Housing, meal plans, parking or books are not covered. Learn more about what&#039;s covered here.','The Arizona Promise Program is a guaranteed scholarship program for eligible Arizona residents that ensures all tuition and fees are covered at Arizona&#039;s public universities. Arizona&#039;s first statewide financial aid program is making higher education more accessible and affordable for Arizona students and families. The promise scholarship is applied after all other aid, scholarships and grants are used. Housing, meal plans, parking or books are not covered. Learn more about what&#039;s covered here.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.azregents.edu/programs/arizona-promise-program',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','b47c4631cade489f26ea2fe0a7e6a9d58c7f2e3b6d4d93facffe23a6d7ea3793','1719c9bb40348edd9676fc534b4026f57e5e9000e0de2d3623de47d34c22b11c',1,1,1,1 FROM sources WHERE root_url='https://www.azregents.edu/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
