INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-95A8DEF2B3871D49FA5A','earth_science',NULL,'Lower Colorado River Monthly Data Report | U.S. Geological Survey','https://www.usgs.gov/centers/arizona-water-science-center/science/lower-colorado-river-monthly-data-report',NULL,'Arizona Water Science Center',NULL,'United States','North America','official_research_institution',NULL,NULL,'2026-10-03T23:07:25.490Z','institutional_primary','en','The Yuma Field Office produces a monthly report of provisional flow data for the Lower Colorado River, its tributaries, and selected diversion and return flow sites. Many of the locations included in the data report are a part of Reclamation’s Decree Accounting Record to comply with Article V of the Decree of the Supreme Court of the United States in Arizona v. California dated March 9, 1964. Other sites included in the report are for planning and forecasting purposes and are used by numerous Colorado River water users. While the flow data in this report is considered provisional, it has been through an internal analyzation and review process. Monthly reports will no longer be accessible online. Please contact Hugh Darling for information on how to receive monthly reports via email.','The Yuma Field Office produces a monthly report of provisional flow data for the Lower Colorado River, its tributaries, and selected diversion and return flow sites. Many of the locations included in the data report are a part of Reclamation’s Decree Accounting Record to comply with Article V of the Decree of the Supreme Court of the United States in Arizona v. California dated March 9, 1964. Other sites included in the report are for planning and forecasting purposes and are used by numerous Colorado River water users. While the flow data in this report is considered provisional, it has been through an internal analyzation and review process. Monthly reports will no longer be accessible online. Please contact Hugh Darling for information on how to receive monthly reports via email.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.usgs.gov/centers/arizona-water-science-center/science/lower-colorado-river-monthly-data-report',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','da185e32859d852473d8293a3ca15c562e01d8d9d3fcfc03d4f39a50fbe18737','95a8def2b3871d49fa5a53c06859e7ca8c0c5db14dbe761fcbaefbece9f0ba6d',1,1,1,1 FROM sources WHERE root_url='https://www.usgs.gov/centers/arizona-water-science-center' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'lower colorado river monthly data report u.s. geological survey the yuma field office produces a monthly report of provisional flow data for the lower colorado river its tributaries and selected diversion and return flow sites. many of the locations included in the data report are a part of reclamation s decree accounting record to comply with article v of the decree of the supreme court of the united states in arizona v. california dated march 9 1964. other sites included in the report are for planning and forecasting purposes and are used by numerous colorado river water users. while the flow data in this report is considered provisional it has been through an internal analyzation and review process. monthly reports will no longer be accessible online. please contact hugh darling for information on how to receive monthly reports via email. earth science',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='95a8def2b3871d49fa5a53c06859e7ca8c0c5db14dbe761fcbaefbece9f0ba6d' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
