INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-2B0F7CDFDD82FC959D70','earth_science',NULL,'Petroleum Geochemistry Research Laboratory Programmed Pyrolysis Method | U.S. Geological Survey','https://www.usgs.gov/media/files/petroleum-geochemistry-research-laboratory-programmed-pyrolysis-method',NULL,'Arizona Water Science Center',NULL,'United States','North America','official_research_institution','2021-09-28T06:00:00Z',NULL,'2026-10-03T23:07:20.936Z','institutional_primary','en','Programmed pyrolysis is a rapid analytical technique used as a screening tool to evaluate source rock hydrocarbon-generating potential and thermal maturity. The Petroleum Geochemistry Research Laboratory (PGRL) method is a modification of the original and most widely used temperature program for this kind of analysis (Barker, 1974; Espitalie and others, 1977; Peters, 1986; Espitalie and Bordenave, 1993; Peters and Rodriguez, 2017).','Programmed pyrolysis is a rapid analytical technique used as a screening tool to evaluate source rock hydrocarbon-generating potential and thermal maturity. The Petroleum Geochemistry Research Laboratory (PGRL) method is a modification of the original and most widely used temperature program for this kind of analysis (Barker, 1974; Espitalie and others, 1977; Peters, 1986; Espitalie and Bordenave, 1993; Peters and Rodriguez, 2017).',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.usgs.gov/media/files/petroleum-geochemistry-research-laboratory-programmed-pyrolysis-method',NULL,4,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','01de44a55d7c872c35eefeaf90c8fa4bf9cb8a1d310aead8e492764c6214ab77','2b0f7cdfdd82fc959d7083568b13fd0139840c05cfbd556c4878803b54da7909',1,1,1,1 FROM sources WHERE root_url='https://www.usgs.gov/centers/arizona-water-science-center' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'petroleum geochemistry research laboratory programmed pyrolysis method u.s. geological survey programmed pyrolysis is a rapid analytical technique used as a screening tool to evaluate source rock hydrocarbon-generating potential and thermal maturity. the petroleum geochemistry research laboratory pgrl method is a modification of the original and most widely used temperature program for this kind of analysis barker 1974 espitalie and others 1977 peters 1986 espitalie and bordenave 1993 peters and rodriguez 2017 . earth science',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='2b0f7cdfdd82fc959d7083568b13fd0139840c05cfbd556c4878803b54da7909' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-571174E96E006AC70DCC','earth_science',NULL,'TM00-01S Analysis and interpretation of reporting environmental data with a non-proper calibration curve for Kjeldahl nitrogen and phosphorus methods; Supplementary Infromation | U.S. Geological Survey','https://www.usgs.gov/media/files/tm00-01s-analysis-and-interpretation-reporting-environmental-data-a-non-proper',NULL,'Arizona Water Science Center',NULL,'United States','North America','official_research_institution','2000-01-07T14:45:30Z',NULL,'2026-10-03T23:07:53.589Z','institutional_primary','en','For the time period between April 20, and October 4, 1999, samples were analyzed by a modified calibration model. An additional low concentration standard was added that improperly eliminated the blank standard from the calibration model. It was initially thought that the blank was critical in the calibration model, by introducing potentially a 0.01 and 0.05 mg/L high bias in results for phosphorus and nitrogen, respectively. Additional data analysis described here, shows that the nonstandard calibration model was still a good model to determine the phosphorus and nitrogen concentrations in environmental samples. The correct 8-point calibration model with the blank standard was developed and all original sample data were processed through the calculation, giving paired results. The variances observed in the data set would be caused entirely by the original nonstandard calibration model a','For the time period between April 20, and October 4, 1999, samples were analyzed by a modified calibration model. An additional low concentration standard was added that improperly eliminated the blank standard from the calibration model. It was initially thought that the blank was critical in the calibration model, by introducing potentially a 0.01 and 0.05 mg/L high bias in results for phosphorus and nitrogen, respectively. Additional data analysis described here, shows that the nonstandard calibration model was still a good model to determine the phosphorus and nitrogen concentrations in environmental samples. The correct 8-point calibration model with the blank standard was developed and all original sample data were processed through the calculation, giving paired results. The variances observed in the data set would be caused entirely by the original nonstandard calibration model a',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.usgs.gov/media/files/tm00-01s-analysis-and-interpretation-reporting-environmental-data-a-non-proper',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','8b707d94e61b98ee917ed0cd97f5418a5003f57540c32f92c5fd30de1efd37ba','571174e96e006ac70dcc20aeb05642fd96f800cdae45a31bfb49852d2b9934e4',1,1,1,1 FROM sources WHERE root_url='https://www.usgs.gov/centers/arizona-water-science-center' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'tm00-01s analysis and interpretation of reporting environmental data with a non-proper calibration curve for kjeldahl nitrogen and phosphorus methods supplementary infromation u.s. geological survey for the time period between april 20 and october 4 1999 samples were analyzed by a modified calibration model. an additional low concentration standard was added that improperly eliminated the blank standard from the calibration model. it was initially thought that the blank was critical in the calibration model by introducing potentially a 0.01 and 0.05 mg l high bias in results for phosphorus and nitrogen respectively. additional data analysis described here shows that the nonstandard calibration model was still a good model to determine the phosphorus and nitrogen concentrations in environmental samples. the correct 8-point calibration model with the blank standard was developed and all original sample data were processed through the calculation giving paired results. the variances observed in the data set would be caused entirely by the original nonstandard calibration model a earth science',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='571174e96e006ac70dcc20aeb05642fd96f800cdae45a31bfb49852d2b9934e4' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
