INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-96742008ED4D2748814C','public_higher_education_research',NULL,'Institutional Review Board','https://www.augusta.edu/research/human-research-program/irb/',NULL,'Augusta University',NULL,'United States','North America','public_graduate_higher_education_research_source','2017-06-07T12:12:20.254Z',NULL,'2026-10-03T23:08:48.757Z','institutional_primary','en','The Institutional Review Board (IRB) Office serves as the central hub for Augusta University’s Enterprise Human Research Protection Program (HRPP). The Augusta University IRB is fully accredited by the Association for the Accreditation of Human Research Protection Programs (AAHRPP), reflecting the University’s commitment to the highest standards of ethical and regulatory oversight in human subjects research. Guided by the ethical principles of the Belmont Report and applicable federal, state, and institutional regulations, the IRB oversees human subjects research to minimize risk, ensure informed consent, and protect research participants.','The Institutional Review Board (IRB) Office serves as the central hub for Augusta University’s Enterprise Human Research Protection Program (HRPP). The Augusta University IRB is fully accredited by the Association for the Accreditation of Human Research Protection Programs (AAHRPP), reflecting the University’s commitment to the highest standards of ethical and regulatory oversight in human subjects research. Guided by the ethical principles of the Belmont Report and applicable federal, state, and institutional regulations, the IRB oversees human subjects research to minimize risk, ensure informed consent, and protect research participants.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.augusta.edu/research/human-research-program/irb/',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','b992c29e8d3a5e380c043ba7ee8437371eb6173bc4f6d0988b0d84eb55c95f23','96742008ed4d2748814c892b2ac62c21db00e3ba11c9da0ba06a3256373eb30d',1,1,1,1 FROM sources WHERE root_url='https://www.augusta.edu/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
