INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-19952412761AE3345CF4','public_higher_education_research',NULL,'Web Accessibility | Bowie State','https://www.bowiestate.edu/about/administration-and-governance/division-of-administration-and-finance/human-resources/web-accessibility.php',NULL,'Bowie State University',NULL,'United States','North America','public_graduate_higher_education_research_source',NULL,NULL,'2026-10-03T23:09:55.553Z','institutional_primary','en','Bowie State University (BSU) is committed to eliminating accessibility barriers to the BSU website in accordance with the university’s mission to empower a diverse population of students. BSU endeavors to ensure that all electronic and information technology resources are accessible for all students, faculty, staff and visitors to promote an inclusive working and learning environment, with universal access to campus resources, irrespective of physical or cognitive abilities. In carrying out this commitment to provide a website that is accessible to all, BSU strives to comply with the Americans with Disabilities Act of 1990 (ADA) . To that end, the BSU website aims to conform to accessibility standards as defined in the Section 508 standards and the Worldwide Web Consortium (W3C) Web Content Accessibility Guidelines (WCAG) 2.0 Level AA standards .','Bowie State University (BSU) is committed to eliminating accessibility barriers to the BSU website in accordance with the university’s mission to empower a diverse population of students. BSU endeavors to ensure that all electronic and information technology resources are accessible for all students, faculty, staff and visitors to promote an inclusive working and learning environment, with universal access to campus resources, irrespective of physical or cognitive abilities. In carrying out this commitment to provide a website that is accessible to all, BSU strives to comply with the Americans with Disabilities Act of 1990 (ADA) . To that end, the BSU website aims to conform to accessibility standards as defined in the Section 508 standards and the Worldwide Web Consortium (W3C) Web Content Accessibility Guidelines (WCAG) 2.0 Level AA standards .',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.bowiestate.edu/about/administration-and-governance/division-of-administration-and-finance/human-resources/web-accessibility.php',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','a8e6c0fb3119bd34aff0c768dc244df76785c84b347956eef330bc37d01e2c4d','19952412761ae3345cf4afd23246f2878cb79fe5027fc7cc3d267074c47dee77',1,1,1,1 FROM sources WHERE root_url='https://www.bowiestate.edu/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'web accessibility bowie state bowie state university bsu is committed to eliminating accessibility barriers to the bsu website in accordance with the university s mission to empower a diverse population of students. bsu endeavors to ensure that all electronic and information technology resources are accessible for all students faculty staff and visitors to promote an inclusive working and learning environment with universal access to campus resources irrespective of physical or cognitive abilities. in carrying out this commitment to provide a website that is accessible to all bsu strives to comply with the americans with disabilities act of 1990 ada . to that end the bsu website aims to conform to accessibility standards as defined in the section 508 standards and the worldwide web consortium w3c web content accessibility guidelines wcag 2.0 level aa standards . public higher education research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='19952412761ae3345cf4afd23246f2878cb79fe5027fc7cc3d267074c47dee77' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
