INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-81042542FC81A540C03F','public_higher_education_research',NULL,'Step 3 of CAP | Bridgewater State University','https://www.bridgew.edu/academics/colleges-departments/college-education-health-sciences/step-3-cap',NULL,'Bridgewater State University',NULL,'United States','North America','public_graduate_higher_education_research_source',NULL,NULL,'2026-10-03T23:09:58.427Z','institutional_primary','en','In Step 3, the TC will work on implementing the plan to work toward the professional practice goal* with the support of the PS and SP. To do this, the TC collects evidence of practice while the PS and SP conduct the first Unannounced Observation (#1) and the second Announced Observation (#2). A pre-conference meeting should be conducted between TC and PS/SP in preparation for Announced Observation #2 as well as timely post-conference meetings to debrief from both the Announced #2 and Unannounced #1 Observations and share feedback.','In Step 3, the TC will work on implementing the plan to work toward the professional practice goal* with the support of the PS and SP. To do this, the TC collects evidence of practice while the PS and SP conduct the first Unannounced Observation (#1) and the second Announced Observation (#2). A pre-conference meeting should be conducted between TC and PS/SP in preparation for Announced Observation #2 as well as timely post-conference meetings to debrief from both the Announced #2 and Unannounced #1 Observations and share feedback.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.bridgew.edu/academics/colleges-departments/college-education-health-sciences/step-3-cap',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','59b25eed870c05cf23e385935245a8b6d62633a3fce19f6d63fe986d5f9f3763','81042542fc81a540c03f2d0361ef2c2d768d0008f19a5d5f25f18a8a8a091a8a',1,1,1,1 FROM sources WHERE root_url='https://www.bridgew.edu/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
