INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-042271555B0968248138','public_higher_education_research',NULL,'Step 4 of CAP | Bridgewater State University','https://www.bridgew.edu/academics/colleges-departments/college-education-health-sciences/step-4-cap',NULL,'Bridgewater State University',NULL,'United States','North America','public_graduate_higher_education_research_source',NULL,NULL,'2026-10-03T23:09:58.376Z','institutional_primary','en','In Step 4, the Formative Assessment is conducted. The PS and SP collaborate as they review evidence collected to date, determine formative assessment ratings on each element, and share these ratings with the TC during the second Three-Way Meeting. The triad revisits and adjusts the plan and/or professional practice goal as necessary.In CAP Step 4, there are three categories of resources from DESERequired FormsSuggested Resource1. Required Forms','In Step 4, the Formative Assessment is conducted. The PS and SP collaborate as they review evidence collected to date, determine formative assessment ratings on each element, and share these ratings with the TC during the second Three-Way Meeting. The triad revisits and adjusts the plan and/or professional practice goal as necessary.In CAP Step 4, there are three categories of resources from DESERequired FormsSuggested Resource1. Required Forms',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.bridgew.edu/academics/colleges-departments/college-education-health-sciences/step-4-cap',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','2f991a75a0a01a93de9fc53505ecc787f20ce372b2a5614d8de4205be6696928','042271555b09682481385875d1fbe501132639a00d873661add3e44f4c76a606',1,1,1,1 FROM sources WHERE root_url='https://www.bridgew.edu/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
