INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-9FA449B6B53FD4B5CC02','public_higher_education_research',NULL,'Step 5 of CAP | Bridgewater State University','https://www.bridgew.edu/academics/colleges-departments/college-education-health-sciences/step-5-cap',NULL,'Bridgewater State University',NULL,'United States','North America','public_graduate_higher_education_research_source',NULL,NULL,'2026-10-03T23:09:58.422Z','institutional_primary','en','Step 5 is the final stage of the CAP Cycle and includes Unannounced Observation #2 and the Summative Assessment, the final task of the CAP Cycle. The PS and SP take a deep dive into all evidence that has been collected in the semester. They jointly determine the rating for each of the Seven Essential Elements based on their collective professional judgment and a thorough examination of evidence that demonstrates the candidate has met all readiness thresholds and is prepared to have positive impact on students.','Step 5 is the final stage of the CAP Cycle and includes Unannounced Observation #2 and the Summative Assessment, the final task of the CAP Cycle. The PS and SP take a deep dive into all evidence that has been collected in the semester. They jointly determine the rating for each of the Seven Essential Elements based on their collective professional judgment and a thorough examination of evidence that demonstrates the candidate has met all readiness thresholds and is prepared to have positive impact on students.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.bridgew.edu/academics/colleges-departments/college-education-health-sciences/step-5-cap',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','a5b7741baf4377b77a4996c425a7ae378bba81f0c0cc7972d9983ec6deac3631','9fa449b6b53fd4b5cc024c6618f2fca4d6843c2cbc7e798bdb2d939713c8779f',1,1,1,1 FROM sources WHERE root_url='https://www.bridgew.edu/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
