INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-71A112FFB54287DBCFC9','public_higher_education_research',NULL,'Jeanne Clery Act | California State University, Bakersfield','https://www.csub.edu/civil-rights-compliance/clery/index.shtml',NULL,'California State University-Bakersfield',NULL,'United States','North America','public_graduate_higher_education_research_source',NULL,NULL,'2026-10-03T23:10:25.697Z','institutional_primary','en','The Jeanne Clery Campus Safety Act (20 U.S.C. Section 1092), most commonly referred to as the Clery Act, requires colleges and universities receiving federal financial assistance to disclose crime statistics and security information. In an effort to increase campus awareness and safety, the Clery Act requires distribution of an annual campus security report to employees and students that include statistics for the previous three years concerning crimes on campus; in California State University (CSU) off campus buildings or property; and on public property within or near the campus, including reports on alcohol and drug use, sexual assault and policies concerning campus security and crime prevention.','The Jeanne Clery Campus Safety Act (20 U.S.C. Section 1092), most commonly referred to as the Clery Act, requires colleges and universities receiving federal financial assistance to disclose crime statistics and security information. In an effort to increase campus awareness and safety, the Clery Act requires distribution of an annual campus security report to employees and students that include statistics for the previous three years concerning crimes on campus; in California State University (CSU) off campus buildings or property; and on public property within or near the campus, including reports on alcohol and drug use, sexual assault and policies concerning campus security and crime prevention.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.csub.edu/civil-rights-compliance/clery/index.shtml',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','0f7eec1ab435c145f6d32c94dead456f97782862027a8aff2ecb53e4aa4d3b60','71a112ffb54287dbcfc9f252bb8222962c51d3dcd08292932446c736b6ecc5c1',1,1,1,1 FROM sources WHERE root_url='https://www.csub.edu/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'jeanne clery act california state university bakersfield the jeanne clery campus safety act 20 u.s.c. section 1092 most commonly referred to as the clery act requires colleges and universities receiving federal financial assistance to disclose crime statistics and security information. in an effort to increase campus awareness and safety the clery act requires distribution of an annual campus security report to employees and students that include statistics for the previous three years concerning crimes on campus in california state university csu off campus buildings or property and on public property within or near the campus including reports on alcohol and drug use sexual assault and policies concerning campus security and crime prevention. public higher education research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='71a112ffb54287dbcfc9f252bb8222962c51d3dcd08292932446c736b6ecc5c1' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
